def regex_match(pattern: str, text: str) -> bool:
    def parse_class(s: str):
        neg = s.startswith('^')
        if neg:
            s = s[1:]
        chars = set()
        i = 0
        while i < len(s):
            if i + 2 < len(s) and s[i+1] == '-':
                start_char = s[i]
                end_char = s[i+2]
                for c in range(ord(start_char), ord(end_char) + 1):
                    chars.add(chr(c))
                i += 3
            else:
                chars.add(s[i])
                i += 1
        return (chars, neg)

    def compile(pattern: str):
        elems = []
        i = 0
        while i < len(pattern):
            if pattern[i] == '(':
                depth = 1
                j = i + 1
                while j < len(pattern) and depth > 0:
                    if pattern[j] == '(':
                        depth += 1
                    elif pattern[j] == ')':
                        depth -= 1
                    j += 1
                inner = pattern[i+1:j-1]
                elems.extend(compile(inner))
                i = j
            elif pattern[i] == '[':
                j = i + 1
                while j < len(pattern) and pattern[j] != ']':
                    j += 1
                elems.append(('class', parse_class(pattern[i+1:j-1])))
                i = j
            elif pattern[i] == '.':
                elems.append(('dot',))
                i += 1
            elif pattern[i] == '\\':
                if i + 1 < len(pattern):
                    elems.append(('char', pattern[i+1]))
                    i += 2
                else:
                    elems.append(('char', '\\'))
                    i += 1
            else:
                elems.append(('char', pattern[i]))
                i += 1

            if i < len(pattern) and pattern[i] in '*+?':
                quant = pattern[i]
                if elems:
                    last = elems[-1]
                    if last[0] == 'class':
                        elems[-1] = ('class', last[1], quant)
                    elif last[0] == 'dot':
                        elems[-1] = ('dot', quant)
                    elif last[0] == 'char':
                        elems[-1] = ('char', last[1], quant)
                i += 1
        return elems

    def get_match_fn(elem):
        t = elem[0]
        if t == 'char':
            c = elem[1]
            return lambda ch, c=c: ch == c
        elif t == 'dot':
            return lambda ch: True
        elif t == 'class':
            chars, neg = elem[1]
            return lambda ch, c=chars, n=neg: (ch in c) != n
        return lambda ch: False

    def dp_match(elems, text):
        m, n = len(elems), len(text)
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = True

        for i in range(1, m + 1):
            elem = elems[i-1]
            quant = elem[-1] if len(elem) == 3 else None
            match_fn = get_match_fn(elem)

            # Handle j=0 explicitly
            if quant in ('*', '?'):
                dp[i][0] = dp[i-1][0]
            else:
                dp[i][0] = False

            for j in range(1, n + 1):
                matches = match_fn(text[j-1])
                if quant is None:
                    dp[i][j] = dp[i-1][j-1] and matches
                elif quant == '?':
                    dp[i][j] = dp[i-1][j] or (dp[i-1][j-1] and matches)
                elif quant == '*':
                    dp[i][j] = dp[i-1][j] or (dp[i][j-1] and matches)
                elif quant == '+':
                    dp[i][j] = (dp[i-1][j] and matches) or (dp[i][j-1] and matches)
        return dp[m][n]

    if '|' in pattern:
        depth = 0
        start = 0
        for i, c in enumerate(pattern):
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            elif c == '|' and depth == 0:
                if regex_match(pattern[:i], text):
                    return True
                start = i + 1
        return regex_match(pattern[start:], text)

    return dp_match(compile(pattern), text)

def json_parse(s: str) -> object:
    if not s:
        raise ValueError("Empty input")
    pos = 0
    n = len(s)

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos] in ' \t\n\r':
            pos += 1

    def error(msg="Invalid JSON"):
        raise ValueError(msg)

    def parse_value():
        skip_ws()
        if pos >= n:
            error("Unexpected end of input")
        c = s[pos]
        if c == '"':
            return parse_string()
        elif c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == 't':
            return parse_literal('true', True)
        elif c == 'f':
            return parse_literal('false', False)
        elif c == 'n':
            return parse_literal('null', None)
        elif c == '-' or c.isdigit():
            return parse_number()
        else:
            error(f"Unexpected character '{c}'")

    def parse_literal(expected, val):
        nonlocal pos
        end = pos + len(expected)
        if end <= n and s[pos:end] == expected:
            pos = end
            return val
        error("Invalid literal")

    def parse_object():
        nonlocal pos
        if s[pos] != '{':
            error("Expected '{'")
        pos += 1
        skip_ws()
        obj = {}
        if pos < n and s[pos] == '}':
            pos += 1
            return obj
        while True:
            skip_ws()
            if pos >= n or s[pos] != '"':
                error("Expected string key")
            key = parse_string()
            skip_ws()
            if pos >= n or s[pos] != ':':
                error("Expected ':'")
            pos += 1
            skip_ws()
            val = parse_value()
            obj[key] = val
            skip_ws()
            if pos < n and s[pos] == ',':
                pos += 1
                skip_ws()
                if pos < n and s[pos] in '}]':
                    error("Trailing comma in object")
                continue
            elif pos < n and s[pos] == '}':
                pos += 1
                return obj
            else:
                error("Expected ',' or '}'")

    def parse_array():
        nonlocal pos
        if s[pos] != '[':
            error("Expected '['")
        pos += 1
        skip_ws()
        arr = []
        if pos < n and s[pos] == ']':
            pos += 1
            return arr
        while True:
            skip_ws()
            val = parse_value()
            arr.append(val)
            skip_ws()
            if pos < n and s[pos] == ',':
                pos += 1
                skip_ws()
                if pos < n and s[pos] == ']':
                    error("Trailing comma in array")
                continue
            elif pos < n and s[pos] == ']':
                pos += 1
                return arr
            else:
                error("Expected ',' or ']'")

    def parse_string():
        nonlocal pos
        if s[pos] != '"':
            error("Expected '\"'")
        pos += 1
        res = []
        while pos < n:
            c = s[pos]
            if c == '"':
                pos += 1
                return ''.join(res)
            elif c == '\\':
                pos += 1
                if pos >= n:
                    error("Unexpected end of string")
                esc = s[pos]
                pos += 1
                if esc == '"':
                    res.append('"')
                elif esc == '\\':
                    res.append('\\')
                elif esc == '/':
                    res.append('/')
                elif esc == 'b':
                    res.append('\b')
                elif esc == 'f':
                    res.append('\f')
                elif esc == 'n':
                    res.append('\n')
                elif esc == 'r':
                    res.append('\r')
                elif esc == 't':
                    res.append('\t')
                elif esc == 'u':
                    if pos + 4 > n:
                        error("Invalid escape sequence")
                    hex_str = s[pos:pos+4]
                    if not all(ch in '0123456789abcdefABCDEF' for ch in hex_str):
                        error("Invalid hex in unicode escape")
                    pos += 4
                    code = int(hex_str, 16)
                    if 0xD800 <= code <= 0xDBFF:
                        if pos + 6 <= n and s[pos:pos+2] == '\\u':
                            hex_str2 = s[pos+2:pos+6]
                            if not all(ch in '0123456789abcdefABCDEF' for ch in hex_str2):
                                error("Invalid hex in unicode escape")
                            code2 = int(hex_str2, 16)
                            if 0xDC00 <= code2 <= 0xDFFF:
                                res.append(chr(0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00)))
                                pos += 6
                            else:
                                res.append(chr(code))
                        else:
                            res.append(chr(code))
                    elif 0xDC00 <= code <= 0xDFFF:
                        res.append(chr(code))
                    else:
                        res.append(chr(code))
                else:
                    error(f"Invalid escape character '\\{esc}'")
            else:
                if ord(c) < 0x20:
                    error("Unescaped control character in string")
                res.append(c)
                pos += 1
        error("Unterminated string")

    def parse_number():
        nonlocal pos
        start = pos
        if s[pos] == '-':
            pos += 1
        if pos >= n or not s[pos].isdigit():
            error("Invalid number")
        if s[pos] == '0':
            pos += 1
            if pos < n and s[pos].isdigit():
                error("Leading zeros not allowed")
        else:
            pos += 1
            while pos < n and s[pos].isdigit():
                pos += 1
        is_float = False
        if pos < n and s[pos] == '.':
            is_float = True
            pos += 1
            if pos >= n or not s[pos].isdigit():
                error("Invalid number: expected digit after '.'")
            while pos < n and s[pos].isdigit():
                pos += 1
        if pos < n and s[pos] in 'eE':
            is_float = True
            pos += 1
            if pos < n and s[pos] in '+-':
                pos += 1
            if pos >= n or not s[pos].isdigit():
                error("Invalid number: expected digit in exponent")
            while pos < n and s[pos].isdigit():
                pos += 1
        num_str = s[start:pos]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    result = parse_value()
    skip_ws()
    if pos < n:
        error("Trailing non-whitespace")
    return result

def json_parse(s: str):
    if not s:
        raise ValueError("Empty input")

    i = 0
    n = len(s)
    DIGITS = set('0123456789')

    def peek():
        return s[i] if i < n else None

    def skip_ws():
        nonlocal i
        while i < n and s[i] in ' \t\n\r':
            i += 1

    def parse_value():
        nonlocal i
        skip_ws()
        if i >= n:
            raise ValueError("Unexpected end of input")

        c = s[i]
        if c == '"':
            return parse_string()
        elif c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == 't':
            return parse_literal('true', True)
        elif c == 'f':
            return parse_literal('false', False)
        elif c == 'n':
            return parse_literal('null', None)
        elif c == '-' or c in DIGITS:
            return parse_number()
        else:
            raise ValueError(f"Unexpected character: {c!r}")

    def parse_literal(name, value):
        nonlocal i
        if s[i:i+len(name)] == name:
            i += len(name)
            return value
        else:
            raise ValueError(f"Invalid literal starting at: {s[i:i+10]!r}")

    def parse_string():
        nonlocal i
        if s[i] != '"':
            raise ValueError("Expected '\"'")
        i += 1
        chars = []
        while i < n:
            c = s[i]
            if c == '"':
                i += 1
                return ''.join(chars)
            elif c == '\\':
                i += 1
                if i >= n:
                    raise ValueError("Unexpected end of input in string")
                esc = s[i]
                i += 1
                if esc == '"':
                    chars.append('"')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '/':
                    chars.append('/')
                elif esc == 'b':
                    chars.append('\b')
                elif esc == 'f':
                    chars.append('\f')
                elif esc == 'n':
                    chars.append('\n')
                elif esc == 'r':
                    chars.append('\r')
                elif esc == 't':
                    chars.append('\t')
                elif esc == 'u':
                    if i + 4 > n:
                        raise ValueError("Incomplete unicode escape")
                    hex_str = s[i:i+4]
                    i += 4
                    for h in hex_str:
                        if h not in '0123456789abcdefABCDEF':
                            raise ValueError(f"Invalid hex digit in unicode escape: {h!r}")
                    code = int(hex_str, 16)
                    if 0xD800 <= code <= 0xDBFF:
                        if i + 6 <= n and s[i] == '\\' and s[i+1] == 'u':
                            i += 2
                            hex_str2 = s[i:i+4]
                            i += 4
                            for h in hex_str2:
                                if h not in '0123456789abcdefABCDEF':
                                    raise ValueError(f"Invalid hex digit in unicode escape: {h!r}")
                            code2 = int(hex_str2, 16)
                            if 0xDC00 <= code2 <= 0xDFFF:
                                code = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00)
                            else:
                                chars.append(chr(code))
                                chars.append(chr(code2))
                        else:
                            chars.append(chr(code))
                    elif 0xDC00 <= code <= 0xDFFF:
                        chars.append(chr(code))
                    else:
                        chars.append(chr(code))
                else:
                    raise ValueError(f"Invalid escape character: {esc!r}")
            else:
                if ord(c) < 0x20:
                    raise ValueError(f"Raw control character in string: {ord(c)!r}")
                chars.append(c)
                i += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal i
        start = i
        if s[i] == '-':
            i += 1

        if i >= n:
            raise ValueError("Unexpected end of input in number")

        if s[i] == '0':
            i += 1
            if i < n and s[i] in DIGITS:
                raise ValueError("Leading zeros not allowed")
        elif s[i] in DIGITS:
            while i < n and s[i] in DIGITS:
                i += 1
        else:
            raise ValueError("Invalid number")

        if i < n and s[i] == '.':
            i += 1
            if i >= n or s[i] not in DIGITS:
                raise ValueError("Invalid number: fraction part missing digits")
            while i < n and s[i] in DIGITS:
                i += 1
            is_float = True
        else:
            is_float = False

        if i < n and s[i] in 'eE':
            i += 1
            if i < n and s[i] in '+-':
                i += 1
            if i >= n or s[i] not in DIGITS:
                raise ValueError("Invalid number: exponent part missing digits")
            while i < n and s[i] in DIGITS:
                i += 1
            is_float = True

        num_str = s[start:i]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    def parse_object():
        nonlocal i
        if s[i] != '{':
            raise ValueError("Expected '{'")
