        skip_ws()
        obj = {}
        if i < n and s[i] == '}':
            i += 1
            return obj

        while True:
            skip_ws()
            if i >= n or s[i] != '"':
                raise ValueError("Expected string key in object")
            key = parse_string()
            skip_ws()
            if i >= n or s[i] != ':':
                raise ValueError("Expected ':'")
            i += 1
            val = parse_value()
            obj[key] = val
            skip_ws()
            if i < n and s[i] == ',':
                i += 1
                skip_ws()
                if i < n and s[i] == '}':
                    raise ValueError("Trailing comma in object")
            elif i < n and s[i] == '}':
                i += 1
                return obj
            else:
                raise ValueError("Expected ',' or '}' in object")

    def parse_array():
        nonlocal i
        if s[i] != '[':
            raise ValueError("Expected '['")
        i += 1
        skip_ws()
        arr = []
        if i < n and s[i] == ']':
            i += 1
            return arr

        while True:
            val = parse_value()
            arr.append(val)
            skip_ws()
            if i < n and s[i] == ',':
                i += 1
                skip_ws()
                if i < n and s[i] == ']':
                    raise ValueError("Trailing comma in array")
            elif i < n and s[i] == ']':
                i += 1
                return arr
            else:
                raise ValueError("Expected ',' or ']' in array")

    result = parse_value()
    skip_ws()
    if i < n:
        raise ValueError("Trailing non-whitespace")
    return result

def json_parse(s: str):
    if not s or not s.strip():
        raise ValueError("Empty input")

    length = len(s)
    cursor = [0]

    def skip_ws():
        while cursor[0] < length and s[cursor[0]] in ' \t\n\r':
            cursor[0] += 1

    def parse_value():
        skip_ws()
        if cursor[0] >= length:
            raise ValueError("Unexpected end of input")
        ch = s[cursor[0]]
        if ch == '{': return parse_object()
        if ch == '[': return parse_array()
        if ch == '"': return parse_string()
        if ch == 't': return parse_literal('true', True)
        if ch == 'f': return parse_literal('false', False)
        if ch == 'n': return parse_literal('null', None)
        if ch == '-' or ch.isdigit(): return parse_number()
        raise ValueError(f"Unexpected character: {ch!r}")

    def parse_literal(expected, value):
        for ch in expected:
            if cursor[0] >= length or s[cursor[0]] != ch:
                raise ValueError("Invalid literal")
            cursor[0] += 1
        return value

    def parse_number():
        start = cursor[0]
        if cursor[0] < length and s[cursor[0]] == '-':
            cursor[0] += 1
        if cursor[0] >= length:
            raise ValueError("Invalid number")
        if s[cursor[0]] == '0':
            cursor[0] += 1
        elif s[cursor[0]] in '123456789':
            cursor[0] += 1
            while cursor[0] < length and s[cursor[0]].isdigit():
                cursor[0] += 1
        else:
            raise ValueError("Invalid number")

        is_float = False
        if cursor[0] < length and s[cursor[0]] == '.':
            is_float = True
            cursor[0] += 1
            if cursor[0] >= length or not s[cursor[0]].isdigit():
                raise ValueError("Invalid number")
            while cursor[0] < length and s[cursor[0]].isdigit():
                cursor[0] += 1

        if cursor[0] < length and s[cursor[0]] in 'eE':
            is_float = True
            cursor[0] += 1
            if cursor[0] < length and s[cursor[0]] in '+-':
                cursor[0] += 1
            if cursor[0] >= length or not s[cursor[0]].isdigit():
                raise ValueError("Invalid number")
            while cursor[0] < length and s[cursor[0]].isdigit():
                cursor[0] += 1

        num_str = s[start:cursor[0]]
        # Strict leading zero check: "0" is ok, "00" or "-00" or "01" are not
        integer_part = num_str.lstrip('-')
        if len(integer_part) > 1 and integer_part[0] == '0':
            raise ValueError("Leading zeros not allowed")

        if is_float:
            return float(num_str)
        return int(num_str)

    def parse_string():
        if s[cursor[0]] != '"':
            raise ValueError("Expected string")
        cursor[0] += 1
        result = []
        while cursor[0] < length:
            ch = s[cursor[0]]
            if ch == '"':
                cursor[0] += 1
                return ''.join(result)
            if ch == '\\':
                cursor[0] += 1
                if cursor[0] >= length:
                    raise ValueError("Unexpected end in string escape")
                esc = s[cursor[0]]
                if esc == '"': result.append('"')
                elif esc == '\\': result.append('\\')
                elif esc == '/': result.append('/')
                elif esc == 'b': result.append('\b')
                elif esc == 'f': result.append('\f')
                elif esc == 'n': result.append('\n')
                elif esc == 'r': result.append('\r')
                elif esc == 't': result.append('\t')
                elif esc == 'u':
                    cursor[0] += 1
                    if cursor[0] + 4 > length:
                        raise ValueError("Invalid unicode escape")
                    hex_str = s[cursor[0]:cursor[0]+4]
                    if not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        raise ValueError("Invalid hex in unicode escape")
                    code_point = int(hex_str, 16)
                    cursor[0] += 4

                    if 0xD800 <= code_point <= 0xDBFF:
                        if cursor[0] + 1 < length and s[cursor[0]] == '\\' and s[cursor[0]+1] == 'u':
                            cursor[0] += 1
                            cursor[0] += 1
                            if cursor[0] + 4 > length:
                                raise ValueError("Invalid unicode escape")
                            hex_str2 = s[cursor[0]:cursor[0]+4]
                            if not all(c in '0123456789abcdefABCDEF' for c in hex_str2):
                                raise ValueError("Invalid hex in unicode escape")
                            low_cp = int(hex_str2, 16)
                            cursor[0] += 4
                            if 0xDC00 <= low_cp <= 0xDFFF:
                                code_point = 0x10000 + (code_point - 0xD800) * 0x400 + (low_cp - 0xDC00)
                    elif 0xDC00 <= code_point <= 0xDFFF:
                        pass

                    if code_point > 0x10FFFF:
                        raise ValueError("Invalid Unicode code point")
                    result.append(chr(code_point))
                else:
                    raise ValueError(f"Invalid escape character: {esc!r}")
            else:
                if ord(ch) < 0x20:
                    raise ValueError(f"Invalid control character in string: {ch!r}")
                result.append(ch)
                cursor[0] += 1
        raise ValueError("Unterminated string")

    def parse_object():
        if s[cursor[0]] != '{':
            raise ValueError("Expected object")
        cursor[0] += 1
        result = {}
        skip_ws()
        if cursor[0] < length and s[cursor[0]] == '}':
            cursor[0] += 1
            return result
        while True:
            skip_ws()
            if cursor[0] >= length:
                raise ValueError("Unterminated object")
            if s[cursor[0]] != '"':
                raise ValueError("Expected string key")
            key = parse_string()
            skip_ws()
            if cursor[0] >= length or s[cursor[0]] != ':':
                raise ValueError("Expected ':'")
            cursor[0] += 1
            skip_ws()
            val = parse_value()
            result[key] = val
            skip_ws()
            if cursor[0] < length:
                if s[cursor[0]] == ',':
                    cursor[0] += 1
                    skip_ws()
                    if cursor[0] < length and s[cursor[0]] == '}':
                        raise ValueError("Trailing comma in object")
                    continue
                elif s[cursor[0]] == '}':
                    cursor[0] += 1
                    return result
                else:
                    raise ValueError("Expected ',' or '}'")
            else:
                raise ValueError("Unterminated object")

    def parse_array():
        if s[cursor[0]] != '[':
            raise ValueError("Expected array")
        cursor[0] += 1
        result = []
        skip_ws()
        if cursor[0] < length and s[cursor[0]] == ']':
            cursor[0] += 1
            return result
        while True:
            skip_ws()
            if cursor[0] >= length:
                raise ValueError("Unterminated array")
            val = parse_value()
            result.append(val)
            skip_ws()
            if cursor[0] < length:
                if s[cursor[0]] == ',':
                    cursor[0] += 1
                    skip_ws()
                    if cursor[0] < length and s[cursor[0]] == ']':
                        raise ValueError("Trailing comma in array")
                    continue
                elif s[cursor[0]] == ']':
                    cursor[0] += 1
                    return result
                else:
                    raise ValueError("Expected ',' or ']'")
            else:
                raise ValueError("Unterminated array")

    result = parse_value()
    skip_ws()
    if cursor[0] < length:
        raise ValueError("Trailing non-whitespace")
    return result

def json_parse(s: str):
    if not s:
        raise ValueError("Empty input")
    val, pos = _parse_value(s, 0)
    pos = _skip_ws(s, pos)
    if pos < len(s):
        raise ValueError("Trailing non-whitespace")
    return val

def _skip_ws(s, pos):
    while pos < len(s) and s[pos] in ' \t\n\r':
        pos += 1
    return pos

def _parse_value(s, pos):
    pos = _skip_ws(s, pos)
    if pos >= len(s):
        raise ValueError("Unexpected end of input")
    c = s[pos]
    if c == '{':
        return _parse_object(s, pos)
    elif c == '[':
        return _parse_array(s, pos)
    elif c == '"':
        return _parse_string(s, pos)
    elif c == 't':
        return _parse_literal(s, pos, 'true', True)
    elif c == 'f':
        return _parse_literal(s, pos, 'false', False)
    elif c == 'n':
