            if i + 3 < n and 0x80 <= b[i+1] <= 0x8F and 0x80 <= b[i+2] <= 0xBF and 0x80 <= b[i+3] <= 0xBF:
                res.append(chr(((byte & 0x07) << 18) | ((b[i+1] & 0x3F) << 12) | ((b[i+2] & 0x3F) << 6) | (b[i+3] & 0x3F)))
                i += 4
            elif i + 2 < n and 0x80 <= b[i+1] <= 0x8F and 0x80 <= b[i+2] <= 0xBF:
                res.append('\ufffd')
                i += 3
            elif i + 1 < n and 0x80 <= b[i+1] <= 0x8F:
                res.append('\ufffd')
                i += 2
            else:
                res.append('\ufffd')
                i += 1
        else:
            res.append('\ufffd')
            i += 1
    return ''.join(res)

import datetime
from typing import Optional

def cron_next(expr: str, after: datetime.datetime) -> datetime.datetime | None:
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Expected 5 fields")

    def parse_field(text: str, min_v: int, max_v: int) -> set[int]:
        values = set()
        for part in text.split(','):
            if not part:
                raise ValueError("Empty part")
            if '/' in part:
                base, step_s = part.split('/', 1)
                if not step_s.isascii() or not step_s.isdigit() or int(step_s) < 1:
                    raise ValueError(f"Invalid step in {part}")
                step = int(step_s)
            else:
                base = part
                step = 1

            if base == '*':
                start, end = min_v, max_v
            elif '-' in base:
                a_s, b_s = base.split('-', 1)
                if not a_s.isascii() or not a_s.isdigit() or not b_s.isascii() or not b_s.isdigit():
                    raise ValueError(f"Invalid range in {part}")
                start, end = int(a_s), int(b_s)
                if start > end:
                    raise ValueError("Range a > b")
            elif base.isascii() and base.isdigit():
                start = int(base)
                end = max_v
            else:
                raise ValueError(f"Invalid item {part}")

            if start < min_v or end > max_v:
                raise ValueError("Out of range")

            for v in range(start, end + 1, step):
                values.add(v)
        if not values:
            raise ValueError("Empty field")
        return values

    minutes = parse_field(fields[0], 0, 59)
    hours = parse_field(fields[1], 0, 23)
    dom_text = fields[2]
    dom = parse_field(dom_text, 1, 31)
    months = parse_field(fields[3], 1, 12)
    dow_text = fields[4]
    dow = parse_field(dow_text, 0, 7)
    # Normalize 7 (Sunday) to 0
    dow = {0 if v == 7 else v for v in dow}

    dom_restricted = not dom_text.startswith('*')
    dow_restricted = not dow_text.startswith('*')

    # Start strictly after `after`, at the next minute boundary
    cand = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    limit = after + datetime.timedelta(days=3000)

    while cand <= limit:
        # Month check
        if cand.month not in months:
            if cand.month == 12:
                cand = cand.replace(year=cand.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                cand = cand.replace(month=cand.month + 1, day=1, hour=0, minute=0)
            continue

        # Day check
        dom_match = cand.day in dom
        # Python weekday: Mon=0..Sun=6. Cron: 0=Sun, 1=Mon..6=Sat.
        cron_dow = cand.isoweekday() % 7
        dow_match = cron_dow in dow

        if dom_restricted and dow_restricted:
            day_ok = dom_match or dow_match
        else:
            day_ok = dom_match and dow_match

        if not day_ok:
            cand = cand.replace(hour=0, minute=0) + datetime.timedelta(days=1)
            continue

        # Hour check
        if cand.hour not in hours:
            found = False
            for h in hours:
                if h > cand.hour:
                    cand = cand.replace(hour=h, minute=0)
                    found = True
                    break
            if not found:
                cand = cand.replace(hour=0, minute=0) + datetime.timedelta(days=1)
            continue

        # Minute check
        if cand.minute not in minutes:
            found = False
            for m in minutes:
                if m > cand.minute:
                    cand = cand.replace(minute=m)
                    found = True
                    break
            if not found:
                cand = cand.replace(hour=0, minute=0) + datetime.timedelta(days=1)
            continue

        return cand

    return None

import datetime as dt

def cron_next(expr: str, after: dt.datetime) -> dt.datetime | None:
    def parse_field(field_str: str, min_val: int, max_val: int) -> tuple[set[int], bool]:
        values = set()
        is_restricted = not field_str.startswith('*')
        if not field_str:
            raise ValueError("Empty field")

        parts = field_str.split(',')
        for part in parts:
            part = part.strip()
            if not part:
                raise ValueError("Empty item")
            step = 1
            if '/' in part:
                base, step_str = part.split('/', 1)
                step_str = step_str.strip()
                if not step_str.isascii() or not step_str.isdigit() or int(step_str) < 1:
                    raise ValueError("Invalid step")
                step = int(step_str)
            else:
                base = part

            if base == '*':
                start, end = min_val, max_val
            elif '-' in base:
                if base.count('-') != 1:
                    raise ValueError("Invalid range")
                a_str, b_str = base.split('-', 1)
                a_str, b_str = a_str.strip(), b_str.strip()
                if not a_str.isascii() or not a_str.isdigit() or not b_str.isascii() or not b_str.isdigit():
                    raise ValueError("Invalid range")
                a, b = int(a_str), int(b_str)
                if a < min_val or b > max_val or a > b:
                    raise ValueError("Invalid range")
                start, end = a, b
            elif base.isascii() and base.isdigit():
                n = int(base)
                if n < min_val or n > max_val:
                    raise ValueError("Out of range")
                start, end = n, max_val
            else:
                raise ValueError("Invalid item")

            curr = start
            while curr <= end:
                values.add(curr)
                curr += step
        return values, is_restricted

    def cron_dow_to_python(cron_dow: int) -> int:
        if cron_dow == 0 or cron_dow == 7:
            return 6
        return (cron_dow - 1) % 7

    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("Invalid expression: expected 5 fields")

    min_set, _ = parse_field(parts[0], 0, 59)
    hour_set, _ = parse_field(parts[1], 0, 23)
    dom_set, dom_restricted = parse_field(parts[2], 1, 31)
    month_set, _ = parse_field(parts[3], 1, 12)
    dow_set_cron, dow_restricted = parse_field(parts[4], 0, 7)

    dow_set = {cron_dow_to_python(d) for d in dow_set_cron}

    current_date = after.date()
    end_date = after.date() + dt.timedelta(days=3000)

    curr = current_date
    while curr <= end_date:
        if curr.month not in month_set:
            curr += dt.timedelta(days=1)
            continue

        dom_match = curr.day in dom_set
        dow_match = curr.weekday() in dow_set

        if dom_restricted and dow_restricted:
            if not (dom_match or dow_match):
                curr += dt.timedelta(days=1)
                continue
        else:
            if not (dom_match and dow_match):
                curr += dt.timedelta(days=1)
                continue

        valid_times = [(h, m) for h in hour_set for m in min_set]
        valid_times.sort()

        start_time = after.time() if curr == after.date() else dt.time(0, 0)

        for h, m in valid_times:
            if dt.time(h, m) > start_time:
                return dt.datetime(curr.year, curr.month, curr.day, h, m)

        curr += dt.timedelta(days=1)

    return None

from datetime import datetime, timedelta

def cron_next(expr: str, after: datetime) -> datetime | None:
    parts = expr.strip().split()
    if len(parts) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    field_ranges = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]
    valid_sets = []
    restricted = []

    for i, (text, (min_v, max_v)) in enumerate(zip(parts, field_ranges)):
        values = set()
        for part in text.split(','):
            if not part:
                raise ValueError("Empty field part")
            if '/' in part:
                base, step_str = part.split('/', 1)
                if not step_str or not step_str.isdigit():
                    raise ValueError("Invalid step")
                step = int(step_str)
                if step < 1:
                    raise ValueError("Step must be >= 1")
                if base == '*':
                    start, end = min_v, max_v
                elif '-' in base:
                    a, b = base.split('-', 1)
                    if not a.isdigit() or not b.isdigit():
                        raise ValueError("Invalid range")
                    start, end = int(a), int(b)
                    if start > end:
                        raise ValueError("Range start > end")
                else:
                    if not base.isdigit():
                        raise ValueError("Invalid start")
                    start = int(base)
                    end = max_v
                if start < min_v or end > max_v:
                    raise ValueError("Out of range")
                values.update(range(start, end + 1, step))
            elif part == '*':
                values.update(range(min_v, max_v + 1))
            elif '-' in part:
                a, b = part.split('-', 1)
                if not a.isdigit() or not b.isdigit():
                    raise ValueError("Invalid range")
                start, end = int(a), int(b)
                if start > end:
                    raise ValueError("Range start > end")
                if start < min_v or end > max_v:
                    raise ValueError("Out of range")
                values.update(range(start, end + 1))
            else:
                if not part.isdigit():
                    raise ValueError("Invalid value")
                v = int(part)
                if v < min_v or v > max_v:
                    raise ValueError("Out of range")
                values.add(v)

        if i == 4:  # day-of-week
            if 7 in values:
                values.discard(7)
                values.add(0)
        valid_sets.append(values)
        restricted.append(not text.startswith('*'))

    minutes, hours, doms, months, dows = valid_sets
    dom_rest, dow_rest = restricted[2], restricted[4]

    # Start from the next minute strictly after `after`
    t = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    # Python weekday: 0=Mon, ..., 6=Sun
    # Cron dow: 0=Sun, 1=Mon, ..., 6=Sat, 7=Sun
    # Mapping: cron_dow = (python_weekday + 1) % 7
    while t <= limit:
        if t.month in months:
            dom_ok = t.day in doms
            dow_ok = (t.weekday() + 1) % 7 in dows
            if dom_rest and dow_rest:
                day_ok = dom_ok or dow_ok
            else:
                day_ok = dom_ok and dow_ok

            if day_ok and t.hour in hours and t.minute in minutes:
                return t

        t += timedelta(minutes=1)

    return None

class Calendar:
    def __init__(self, k: int):
        self.k = k
        self.booked = []

    def book(self, start: int, end: int) -> bool:
        # Count how many existing bookings cover `start`
        count = sum(1 for s, e in self.booked if s <= start < e)
        if count >= self.k:
            return False

        # Collect events strictly inside [start, end)
        events = []
        for s, e in self.booked:
            if s > start and s < end:
                events.append((s, 1))
            if e > start and e <= end:
                events.append((e, -1))

        # Sort by time. Ties are broken by delta (-1 before 1), 
        # correctly handling half-open interval boundaries.
        events.sort()

        for t, delta in events:
            if t >= end:
                break
            count += delta
            if count >= self.k:
                return False

        self.booked.append((start, end))
        return True

class Calendar:
    def __init__(self, k: int):
        self.k = k
        self.bookings = []

    def book(self, start: int, end: int) -> bool:
        # Identify critical points where the overlap count might change or be maximal.
        # The overlap count (depth) increases at interval starts.
        # We need to check if adding [start, end) causes any point to have > k overlaps.
        # This is equivalent to checking if any point in [start, end) is already covered by >= k intervals.
        # The depth function is piecewise constant and increases at start points.
        # Thus, we only need to check the depth at 'start' and at any existing interval start 's' 
        # such that start <= s < end.

        critical_points = {start}
        for s, e in self.bookings:
            if start <= s < end:
                critical_points.add(s)

        # Check depth at each critical point
        for t in critical_points:
            count = 0
            for s, e in self.bookings:
                if s <= t < e:
                    count += 1
            if count >= self.k:
                return False

        self.bookings.append((start, end))
        return True

def min_semesters(n: int, relations: list[list[int]], k: int) -> int:
    # Precompute prerequisite bitmasks for each course (0-indexed)
    prereq = [0] * n
    for a, b in relations:
        prereq[b - 1] |= (1 << (a - 1))

    limit = 1 << n
    dp = [float('inf')] * limit
    dp[0] = 0

    # Precompute population counts for all masks up to 2^n
    popcount = [0] * limit
    for i in range(1, limit):
        popcount[i] = popcount[i >> 1] + (i & 1)

    full_mask = limit - 1
    for mask in range(limit):
        if dp[mask] == float('inf'):
            continue
        if mask == full_mask:
            break

        # Find courses that are available to take next
        avail = 0
        for i in range(n):
            if not (mask >> i) & 1 and (prereq[i] & mask) == prereq[i]:
                avail |= (1 << i)

        if avail == 0:
            continue

        # We only need to consider subsets of available courses of size exactly min(k, len(avail))
        # Taking more courses is always at least as good as taking fewer.
        target = min(k, popcount[avail])

        # Iterate over all submasks of avail
        s = avail
        while s > 0:
            if popcount[s] == target:
                next_mask = mask | s
                if dp[next_mask] > dp[mask] + 1:
                    dp[next_mask] = dp[mask] + 1
            s = (s - 1) & avail

    return dp[full_mask]

def poly_expand(expr: str) -> str:
    """
    Expands a polynomial in x with integer coefficients.
    Grammar:
      expr := term (('+' | '-') term)*
      term := unary ('*' unary)*
      unary := '-' unary | power
      power := atom ('^' INT)?
      atom := INT | 'x' | '(' expr ')'
    INT is a non-negative decimal integer; exponent <= 20.
    """

    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def skip_ws(self):
            while self.pos < self.n and self.s[self.pos] == ' ':
                self.pos += 1

        def peek(self):
            self.skip_ws()
            if self.pos < self.n:
                return self.s[self.pos]
            return None

        def consume(self):
            self.skip_ws()
            if self.pos >= self.n:
                raise ValueError("Unexpected end of input")
            ch = self.s[self.pos]
            self.pos += 1
            return ch

        def parse_int(self):
            self.skip_ws()
            if self.pos >= self.n or not self.s[self.pos].isdigit():
                raise ValueError("Expected integer")
            start = self.pos
            while self.pos < self.n and self.s[self.pos].isdigit():
                self.pos += 1
            return int(self.s[start:self.pos])

        def parse_expr(self):
            poly = self.parse_term()
            while True:
                ch = self.peek()
                if ch == '+':
                    self.consume()
                    term_poly = self.parse_term()
                    poly = self.add_poly(poly, term_poly)
                elif ch == '-':
                    self.consume()
                    term_poly = self.parse_term()
                    poly = self.sub_poly(poly, term_poly)
                else:
                    break
            return poly

        def parse_term(self):
            poly = self.parse_unary()
            while self.peek() == '*':
                self.consume()
                next_poly = self.parse_unary()
                poly = self.mul_poly(poly, next_poly)
            return poly

        def parse_unary(self):
            if self.peek() == '-':
                self.consume()
                inner_poly = self.parse_unary()
                return self.neg_poly(inner_poly)
            return self.parse_power()

        def parse_power(self):
            poly = self.parse_atom()
            if self.peek() == '^':
                self.consume()
                exp = self.parse_int()
                if exp > 20:
                    raise ValueError("Exponent > 20")
                # Compute poly ^ exp
                res = {0: 1}
                for _ in range(exp):
                    res = self.mul_poly(res, poly)
                return res
            return poly

        def parse_atom(self):
            ch = self.peek()
            if ch is None:
                raise ValueError("Unexpected end of input")

            if ch == '(':
                self.consume()
                poly = self.parse_expr()
                if self.peek() != ')':
                    raise ValueError("Missing closing parenthesis")
                self.consume()
                return poly
            elif ch == 'x':
                self.consume()
                return {1: 1}
            elif ch.isdigit():
                val = self.parse_int()
                return {0: val}
            else:
                raise ValueError(f"Unexpected character: {ch}")

        def add_poly(self, p1, p2):
            if not p1: return p2
            if not p2: return p1
            res = dict(p1)
            for d, c in p2.items():
                res[d] = res.get(d, 0) + c
            return {d: c for d, c in res.items() if c != 0}

        def sub_poly(self, p1, p2):
            if not p1: return self.neg_poly(p2)
            if not p2: return p1
            res = dict(p1)
            for d, c in p2.items():
                res[d] = res.get(d, 0) - c
            return {d: c for d, c in res.items() if c != 0}

        def mul_poly(self, p1, p2):
            if not p1 or not p2: return {}
            res = {}
            for d1, c1 in p1.items():
                for d2, c2 in p2.items():
                    d = d1 + d2
                    res[d] = res.get(d, 0) + c1 * c2
            return {d: c for d, c in res.items() if c != 0}

        def neg_poly(self, p):
            if not p: return {}
            return {d: -c for d, c in p.items() if -c != 0}

    def format_poly(poly):
        if not poly:
            return "0"

        degrees = sorted(poly.keys(), reverse=True)
        terms = []
        first = True

        for d in degrees:
            c = poly[d]
            if c == 0: continue

            if d == 0:
                term_str = str(c)
            else:
                if c == 1:
                    coeff_str = ""
                elif c == -1:
                    coeff_str = "-"
                else:
                    coeff_str = str(c)

                if d == 1:
                    term_str = coeff_str + "x"
                else:
                    term_str = coeff_str + "x^" + str(d)

            if first:
                terms.append(term_str)
                first = False
            else:
                if term_str.startswith("-"):
                    terms.append(" - " + term_str[1:])
                else:
                    terms.append(" + " + term_str)

        return "".join(terms)

    parser = Parser(expr)
    result_poly = parser.parse_expr()

    # Check if entire string was consumed
    parser.skip_ws()
    if parser.pos < parser.n:
        raise ValueError("Unexpected trailing characters")

    return format_poly(result_poly)

def poly_expand(expr: str) -> str:
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isspace():
                i += 1
            elif s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('INT', int(s[i:j])))
                i = j
            elif s[i] in '+-*/^()':
                tokens.append((s[i], s[i]))
                i += 1
            elif s[i] == 'x':
                tokens.append(('x', 'x'))
                i += 1
            else:
                raise ValueError(f"Invalid character: {s[i]}")
        return tokens

    def make_poly(c):
        return [c]

    def make_x_poly():
        return [0, 1]

    def trim(poly):
        res = list(poly)
        while len(res) > 1 and res[-1] == 0:
            res.pop()
        return res

    def add_poly(a, b):
        n = max(len(a), len(b))
        res = [0] * n
        for i in range(n):
            res[i] = (a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0)
        return trim(res)

    def sub_poly(a, b):
        n = max(len(a), len(b))
        res = [0] * n
        for i in range(n):
            res[i] = (a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0)
        return trim(res)

    def neg_poly(a):
        return [-c for c in a]

    def mul_poly(a, b):
        if not a or not b:
            return [0]
        res = [0] * (len(a) + len(b) - 1)
        for i, ca in enumerate(a):
            if ca == 0: continue
            for j, cb in enumerate(b):
                res[i+j] += ca * cb
        return trim(res)

    def pow_poly(a, n):
        if n == 0:
            return [1]
        if n == 1:
            return trim(a)
        res = [1]
        base = trim(a)
        while n > 0:
            if n % 2 == 1:
                res = mul_poly(res, base)
            base = mul_poly(base, base)
            n //= 2
        return trim(res)

    def format_poly(poly):
        if not poly or all(c == 0 for c in poly):
            return "0"

        terms = []
        for i in range(len(poly) - 1, -1, -1):
            c = poly[i]
            if c == 0:
                continue
            if i == 0:
                terms.append((c, str(c)))
            elif i == 1:
                if c == 1: terms.append((c, "x"))
                elif c == -1: terms.append((c, "-x"))
                else: terms.append((c, f"{c}x"))
            else:
                if c == 1: terms.append((c, f"x^{i}"))
                elif c == -1: terms.append((c, f"-x^{i}"))
                else: terms.append((c, f"{c}x^{i}"))

        if not terms:
            return "0"

        res = terms[0][1]
        for c, t in terms[1:]:
            if c > 0:
                res += f" + {t}"
            else:
                res += f" - {t[1:]}"
        return res

    tokens = tokenize(expr)
    pos = 0
    n = len(tokens)

    def peek():
        return tokens[pos] if pos < n else None

    def consume(expected=None):
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of input")
        if expected and tok[1] != expected:
            raise ValueError(f"Expected '{expected}', got '{tok[1]}'")
        pos += 1
        return tok

    def parse_expr():
        poly = parse_term()
        while peek() and peek()[1] in ('+', '-'):
            op = consume()[1]
            right = parse_term()
            if op == '+':
                poly = add_poly(poly, right)
            else:
                poly = sub_poly(poly, right)
        return poly

    def parse_term():
        poly = parse_unary()
        while peek() and peek()[1] == '*':
            consume()
            right = parse_unary()
            poly = mul_poly(poly, right)
        return poly

    def parse_unary():
        if peek() and peek()[1] == '-':
            consume()
            right = parse_unary()
            return neg_poly(right)
        return parse_power()

    def parse_power():
        poly = parse_atom()
        if peek() and peek()[1] == '^':
            consume()
            exp_tok = consume()
            if exp_tok[0] != 'INT':
                raise ValueError("Expected integer exponent")
            exp = exp_tok[1]
            if exp > 20:
                raise ValueError("Exponent > 20")
            poly = pow_poly(poly, exp)
        return poly

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of input")
