            poly = parse_expr()
            consume(')')
            return poly
        else:
            raise ValueError(f"Unexpected token: {tok}")

    result_poly = parse_expr()
    if pos != n:
        raise ValueError("Unexpected tokens at end of input")

    return format_poly(result_poly)

def poly_expand(expr: str) -> str:
    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def skip_spaces(self):
            while self.pos < self.n and self.s[self.pos] == ' ':
                self.pos += 1

        def match(self, char: str) -> bool:
            if self.pos < self.n and self.s[self.pos] == char:
                self.pos += 1
                return True
            return False

        def expect(self, char: str):
            if not self.match(char):
                raise ValueError(f"Expected '{char}' at position {self.pos}")

        def parse_int(self) -> int:
            start = self.pos
            if self.pos >= self.n or not self.s[self.pos].isdigit():
                raise ValueError(f"Expected integer at position {self.pos}")
            while self.pos < self.n and self.s[self.pos].isdigit():
                self.pos += 1
            return int(self.s[start:self.pos])

        def parse_atom(self) -> dict[int, int]:
            self.skip_spaces()
            if self.pos >= self.n:
                raise ValueError("Unexpected end of input")
            ch = self.s[self.pos]
            if ch.isdigit():
                return {0: self.parse_int()}
            elif ch == 'x':
                self.pos += 1
                return {1: 1}
            elif ch == '(':
                self.pos += 1
                poly = self.parse_expr()
                self.expect(')')
                return poly
            else:
                raise ValueError(f"Unexpected character '{ch}' at position {self.pos}")

        def parse_power(self) -> dict[int, int]:
            poly = self.parse_atom()
            self.skip_spaces()
            if self.match('^'):
                exp = self.parse_int()
                if exp > 20:
                    raise ValueError("Exponent > 20")
                res = {0: 1}
                for _ in range(exp):
                    res = poly_mul(res, poly)
                return res
            return poly

        def parse_unary(self) -> dict[int, int]:
            self.skip_spaces()
            if self.match('-'):
                poly = self.parse_unary()
                return {deg: -coeff for deg, coeff in poly.items()}
            return self.parse_power()

        def parse_term(self) -> dict[int, int]:
            poly = self.parse_unary()
            self.skip_spaces()
            while self.match('*'):
                next_poly = self.parse_unary()
                poly = poly_mul(poly, next_poly)
                self.skip_spaces()
            return poly

        def parse_expr(self) -> dict[int, int]:
            poly = self.parse_term()
            self.skip_spaces()
            while True:
                if self.match('+'):
                    next_poly = self.parse_term()
                    poly = poly_add(poly, next_poly)
                elif self.match('-'):
                    next_poly = self.parse_term()
                    poly = poly_sub(poly, next_poly)
                else:
                    break
                self.skip_spaces()
            return poly

    def poly_add(a, b):
        res = dict(a)
        for deg, coeff in b.items():
            res[deg] = res.get(deg, 0) + coeff
        return {d: c for d, c in res.items() if c != 0}

    def poly_sub(a, b):
        res = dict(a)
        for deg, coeff in b.items():
            res[deg] = res.get(deg, 0) - coeff
        return {d: c for d, c in res.items() if c != 0}

    def poly_mul(a, b):
        res = {}
        for d1, c1 in a.items():
            for d2, c2 in b.items():
                d = d1 + d2
                res[d] = res.get(d, 0) + c1 * c2
        return {d: c for d, c in res.items() if c != 0}

    parser = Parser(expr)
    poly = parser.parse_expr()
    parser.skip_spaces()
    if parser.pos != parser.n:
        raise ValueError("Unexpected characters at end of input")

    if not poly:
        return "0"

    terms = []
    for deg in sorted(poly.keys(), reverse=True):
        coeff = poly[deg]
        if deg == 0:
            t = str(abs(coeff))
        elif deg == 1:
            t = "x" if abs(coeff) == 1 else f"{abs(coeff)}x"
        else:
            t = f"x^{deg}" if abs(coeff) == 1 else f"{abs(coeff)}x^{deg}"
        if coeff < 0:
            terms.append(f"- {t}")
        else:
            terms.append(f"+ {t}")

    res = " ".join(terms)
    if res.startswith("+ "):
        res = res[2:]
    elif res.startswith("- "):
        res = res[2:]
    return res

def poly_expand(expr: str) -> str:
    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isspace():
                i += 1
                continue
            if s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append(('INT', int(s[i:j])))
                i = j
            elif s[i] == 'x':
                tokens.append(('X', 'x'))
                i += 1
            elif s[i] == '+':
                tokens.append(('PLUS', '+'))
                i += 1
            elif s[i] == '-':
                tokens.append(('MINUS', '-'))
                i += 1
            elif s[i] == '*':
                tokens.append(('STAR', '*'))
                i += 1
            elif s[i] == '^':
                tokens.append(('CARET', '^'))
                i += 1
            elif s[i] == '(':
                tokens.append(('LPAREN', '('))
                i += 1
            elif s[i] == ')':
                tokens.append(('RPAREN', ')'))
                i += 1
            else:
                raise ValueError(f"Unexpected character: {s[i]}")
        tokens.append(('EOF', None))
        return tokens

    def poly_add(p1, p2):
        res = {}
        for d, c in p1.items():
            res[d] = res.get(d, 0) + c
        for d, c in p2.items():
            res[d] = res.get(d, 0) + c
        return {d: c for d, c in res.items() if c != 0}

    def poly_sub(p1, p2):
        res = {}
        for d, c in p1.items():
            res[d] = res.get(d, 0) + c
        for d, c in p2.items():
            res[d] = res.get(d, 0) - c
        return {d: c for d, c in res.items() if c != 0}

    def poly_mul(p1, p2):
        res = {}
        for d1, c1 in p1.items():
            for d2, c2 in p2.items():
                d = d1 + d2
                res[d] = res.get(d, 0) + c1 * c2
        return {d: c for d, c in res.items() if c != 0}

    def poly_pow(p, n):
        if n == 0:
            return {0: 1}
        if n == 1:
            return p.copy()
        res = {0: 1}
        base = p.copy()
        while n > 0:
            if n % 2 == 1:
                res = poly_mul(res, base)
            base = poly_mul(base, base)
            n //= 2
        return res

    def poly_neg(p):
        return {d: -c for d, c in p.items()}

    tokens = tokenize(expr)
    pos = 0
    n = len(tokens)

    def current():
        return tokens[pos]

    def consume(expected_type=None):
        nonlocal pos
        tok = tokens[pos]
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {tok}")
        pos += 1
        return tok

    def parse_expr():
        p = parse_term()
        while current()[0] in ('PLUS', 'MINUS'):
            op = consume()[0]
            right = parse_term()
            if op == 'PLUS':
                p = poly_add(p, right)
            else:
                p = poly_sub(p, right)
        return p

    def parse_term():
        p = parse_unary()
        while current()[0] == 'STAR':
            consume()
            right = parse_unary()
            p = poly_mul(p, right)
        return p

    def parse_unary():
        if current()[0] == 'MINUS':
            consume()
            p = parse_unary()
            return poly_neg(p)
        return parse_power()

    def parse_power():
        atom = parse_atom()
        if current()[0] == 'CARET':
            consume()
            exp_tok = consume('INT')
            exp = exp_tok[1]
            if exp > 20:
                raise ValueError("Exponent too large")
            return poly_pow(atom, exp)
        return atom

    def parse_atom():
        tok = current()
        if tok[0] == 'INT':
            consume()
            return {0: tok[1]}
        elif tok[0] == 'X':
            consume()
            return {1: 1}
        elif tok[0] == 'LPAREN':
            consume()
            p = parse_expr()
            consume('RPAREN')
            return p
        else:
            raise ValueError(f"Unexpected token: {tok}")

    p = parse_expr()
    if pos != n:
        raise ValueError("Unexpected trailing tokens")

    if not p:
        return "0"

    sorted_degrees = sorted(p.keys(), reverse=True)
    terms = []
    for i, d in enumerate(sorted_degrees):
        c = p[d]
        if c == 0:
            continue
        if i == 0:
            if c < 0:
                terms.append("-")
                c = -c
        else:
            if c < 0:
                terms.append(" - ")
                c = -c
            else:
                terms.append(" + ")

        if d == 0:
            terms.append(str(c))
        elif d == 1:
            if c == 1:
                terms.append("x")
            else:
                terms.append(f"{c}x")
        else:
            if c == 1:
                terms.append(f"x^{d}")
            else:
                terms.append(f"{c}x^{d}")
    return "".join(terms)

import math

def rational_eval(expr: str) -> str:
    pos = 0
    n = len(expr)

    def skip_spaces():
        nonlocal pos
        while pos < n and expr[pos] == ' ':
            pos += 1

    def consume(expected=None):
        skip_spaces()
        if pos >= n:
            raise ValueError("Unexpected end of input")
        ch = expr[pos]
        if expected and ch != expected:
            raise ValueError(f"Expected '{expected}', got '{ch}'")
        nonlocal pos
        pos += 1
        return ch

    def parse_int():
        skip_spaces()
        if pos >= n or not expr[pos].isdigit():
            raise ValueError("Expected integer")
        start = pos
        while pos < n and expr[pos].isdigit():
            pos += 1
        return int(expr[start:pos])

    def parse_expr():
        left = parse_term()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in '+-':
                op = consume()
                right = parse_term()
                if op == '+':
                    left = add(left, right)
                else:
                    left = sub(left, right)
            else:
                break
        return left

    def parse_term():
        left = parse_unary()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in '*/':
                op = consume()
                right = parse_unary()
                if op == '*':
                    left = mul(left, right)
                else:
                    left = div(left, right)
            else:
                break
        return left

    def parse_unary():
        skip_spaces()
        if pos < n and expr[pos] == '-':
            consume()
            val = parse_unary()
            return (-val[0], val[1])
        return parse_power()

    def parse_power():
        base = parse_atom()
        skip_spaces()
        if pos < n and expr[pos] == '^':
            consume()
            exp = parse_unary()
            return pow_rational(base, exp)
        return base

    def parse_atom():
        skip_spaces()
        if pos >= n:
            raise ValueError("Unexpected end of input")
        ch = expr[pos]
        if ch == '(':
            consume('(')
            val = parse_expr()
            consume(')')
            return val
        elif ch.isdigit():
            return (parse_int(), 1)
        else:
            raise ValueError(f"Unexpected character '{ch}'")

    def gcd(a, b):
        return math.gcd(a, b)

    def normalize(n, d):
        if d == 0:
            raise ZeroDivisionError("Division by zero")
        if d < 0:
            n, d = -n, d
        g = gcd(abs(n), d)
        return (n // g, d // g)

    def add(a, b):
        return normalize(a[0]*b[1] + b[0]*a[1], a[1]*b[1])

    def sub(a, b):
        return normalize(a[0]*b[1] - b[0]*a[1], a[1]*b[1])

    def mul(a, b):
        return normalize(a[0]*b[0], a[1]*b[1])

    def div(a, b):
        if b[0] == 0:
            raise ZeroDivisionError("Division by zero")
        return normalize(a[0]*b[1], a[1]*b[0])

    def pow_rational(base, exp):
        if base[0] == 0:
            if exp[1] != 1 or exp[0] < 0:
                raise ZeroDivisionError("0 to a negative power")
            if exp[0] == 0:
                return (1, 1)
            return (0, 1)

        if exp[1] != 1:
            raise ValueError("Exponent must be an integer")
        e = exp[0]

        if e < 0:
            res = pow_rational(base, (abs(e), 1))
            return normalize(res[1], res[0])

        res = (1, 1)
        b = base
        while e > 0:
            if e & 1:
                res = mul(res, b)
            b = mul(b, b)
            e >>= 1
        return res

    try:
        result = parse_expr()
        skip_spaces()
        if pos < n:
            raise ValueError("Unexpected characters after expression")
        n_val, d_val = result
        if d_val == 1:
            return str(n_val)
        else:
            return f"{n_val}/{d_val}"
    except ValueError:
        raise
    except ZeroDivisionError:
        raise

