                return Fraction(1)
            return base ** exp_int
        return base

    def parse_atom():
        tok = peek()
        if tok[0] == 'INT':
            consume()
            return Fraction(int(tok[1]))
        elif tok[0] == '(':
            consume()
            val = parse_expr()
            if peek()[0] != ')':
