def rational_eval(expr: str) -> str:
    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        def peek(self):
            return self.s[self.i] if self.i < self.n else None

        def advance(self):
            self.i += 1

        def skip(self):
            while self.i < self.n and self.s[self.i] == ' ':
                self.i += 1

        def parse(self):
            res = self.expr()
            self.skip()
            if self.i != self.n:
                raise ValueError("Malformed input")
            return str(res)

        def expr(self):
            left = self.term()
            while True:
                self.skip()
                op = self.peek()
                if op == '+':
                    self.advance()
                    left = left + self.term()
                elif op == '-':
                    self.advance()
                    left = left - self.term()
                else:
                    break
            return left

        def term(self):
            left = self.unary()
            while True:
                self.skip()
                op = self.peek()
                if op == '*':
                    self.advance()
                    left = left * self.unary()
                elif op == '/':
                    self.advance()
                    right = self.unary()
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    left = left / right
                else:
                    break
            return left

        def unary(self):
            self.skip()
            if self.peek() == '-':
                self.advance()
                return -self.unary()
            return self.power()

        def power(self):
            base = self.atom()
            self.skip()
            if self.peek() == '^':
                self.advance()
                exp = self.unary()
                if not isinstance(exp, int):
                    raise ValueError("Exponent must be an integer")
                if base == 0 and exp < 0:
                    raise ZeroDivisionError("0 to a negative power")
                return base ** exp
            return base

        def atom(self):
            self.skip()
            ch = self.peek()
            if ch == '(':
                self.advance()
                val = self.expr()
                self.skip()
                if self.peek() != ')':
                    raise ValueError("Malformed input")
                self.advance()
                return val
            elif ch is not None and ch.isdigit():
                start = self.i
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
                return int(self.s[start:self.i])
            else:
                raise ValueError("Malformed input")

    return Parser(expr).parse()

