        chunk_words = []
        h, rem = divmod(chunk, 100)
        if h > 0:
            chunk_words.append(f"{ones[h]} Hundred")
        if rem == 0:
            pass
        elif rem < 20:
            chunk_words.append(ones[rem])
        else:
            t, o = divmod(rem, 10)
            chunk_words.append(tens[t])
