def sliding_median(nums: list[int], k: int) -> list[float]:
    if not nums or k <= 0:
        return []

    lo = []  # max-heap (stores negated values)
    hi = []  # min-heap
    balance = 0
    delayed = defaultdict(int)

    def clean_top():
        while lo and delayed.get(-lo[0], 0) > 0:
            delayed[-lo[0]] -= 1
            heapq.heappop(lo)
        while hi and delayed.get(hi[0], 0) > 0:
            delayed[hi[0]] -= 1
            heapq.heappop(hi)

    def rebalance():
        nonlocal balance
        while balance > 1:
            clean_top()
            heapq.heappush(hi, -heapq.heappop(lo))
            balance -= 2
        while balance < 0:
            clean_top()
            heapq.heappush(lo, -heapq.heappop(hi))
            balance += 2

    def add(val: int) -> None:
        nonlocal balance
        if not lo or val <= -lo[0]:
            heapq.heappush(lo, -val)
            balance += 1
        else:
            heapq.heappush(hi, val)
            balance -= 1
        rebalance()
        clean_top()

    def remove(val: int) -> None:
        nonlocal balance
        clean_top()
        if val <= -lo[0]:
            balance -= 1
        else:
            balance += 1
        delayed[val] += 1
        rebalance()
        clean_top()

    # Initialize first window
    for x in nums[:k]:
        add(x)

    clean_top()
    res = []
    if k % 2 == 1:
        res.append(-float(lo[0]))
    else:
        res.append((-lo[0] + hi[0]) / 2.0)

    for i in range(k, len(nums)):
        remove(nums[i - k])
        add(nums[i])
        clean_top()
        if k % 2 == 1:
            res.append(-float(lo[0]))
        else:
            res.append((-lo[0] + hi[0]) / 2.0)

    return res

