from collections import defaultdict

def sliding_median(nums: list[int], k: int) -> list[float]:
    lo = []  # max-heap (stores -x)
    hi = []  # min-heap (stores x)
    delayed = defaultdict(int)
    lo_size = 0
    hi_size = 0

    def prune(heap):
        while heap:
            top = heap[0] if heap is hi else -heap[0]
            if delayed.get(top, 0) > 0:
                heapq.heappop(heap)
                delayed[top] -= 1
                if delayed[top] == 0:
                    del delayed[top]
            else:
                break

    def rebalance():
        nonlocal lo_size, hi_size
        if lo_size > hi_size + 1:
            prune(lo)
            val = -heapq.heappop(lo)
            heapq.heappush(hi, val)
            lo_size -= 1
            hi_size += 1
        elif lo_size < hi_size:
            prune(hi)
            val = heapq.heappop(hi)
            heapq.heappush(lo, -val)
            hi_size -= 1
            lo_size += 1

    def add(num):
        nonlocal lo_size, hi_size
        if not lo or num <= -lo[0]:
            heapq.heappush(lo, -num)
            lo_size += 1
        else:
            heapq.heappush(hi, num)
            hi_size += 1
        rebalance()

    def remove(num):
        nonlocal lo_size, hi_size
        delayed[num] += 1
        if num <= -lo[0]:
            lo_size -= 1
        else:
            hi_size -= 1
        rebalance()

    def get_median():
        prune(lo)
        prune(hi)
        if k % 2 == 1:
            return float(-lo[0])
        else:
            return (-lo[0] + hi[0]) / 2.0

    res = []
    for i, x in enumerate(nums):
        add(x)
        if i >= k:
            remove(nums[i - k])
        if i >= k - 1:
            res.append(get_median())
    return res

