def max_points(points: list[tuple[int, int]]) -> int:
    n = len(points)
    if n <= 2:
        return n

    max_count = 0
    for i in range(n):
        slope_counts = {}
        duplicate = 0
        for j in range(i + 1, n):
            dx = points[j][0] - points[i][0]
            dy = points[j][1] - points[i][1]
            if dx == 0 and dy == 0:
                duplicate += 1
            else:
                g = math.gcd(dx, dy)
                dx //= g
                dy //= g
                if dx < 0:
                    dx = -dx
                    dy = -dy
                elif dx == 0 and dy < 0:
                    dy = -dy
                key = (dy, dx)
                slope_counts[key] = slope_counts.get(key, 0) + 1

        current_max = 1 + duplicate
        if slope_counts:
            current_max += max(slope_counts.values())
        if current_max > max_count:
            max_count = current_max

    return max_count

