def skyline(buildings: list[list[int]]) -> list[list[int]]:
    events = []
    for l, r, h in buildings:
        events.append((l, h))
        events.append((r, -h))
    events.sort()

    res = []
    prev_max = 0
    heap = [0]  # max-heap storing negative heights
    removed = {}

    for x, h in events:
        if h > 0:
            heapq.heappush(heap, -h)
        else:
            height_to_remove = -h
            removed[height_to_remove] = removed.get(height_to_remove, 0) + 1

        # Lazy removal: pop expired max heights from the heap top
        while -heap[0] in removed:
            rem_h = heapq.heappop(heap)
            removed[-rem_h] -= 1
            if removed[-rem_h] == 0:
                del removed[-rem_h]

        curr_max = -heap[0]
        if curr_max != prev_max:
            if res and res[-1][0] == x:
                res[-1][1] = curr_max
            else:
                res.append([x, curr_max])
            prev_max = curr_max

    return res

