def skyline(buildings: list[list[int]]) -> list[list[int]]:
    events = []
    for l, r, h in buildings:
        events.append((l, -h, r))
        events.append((r, h, r))
    events.sort()

    pq = [(0, float('inf'))]
    last_h = 0
    res = []

    for x, h, r in events:
        if h < 0:
            heapq.heappush(pq, (-h, r))
        while pq[0][1] <= x:
            heapq.heappop(pq)
        cur_h = -pq[0][0]
        if cur_h != last_h:
            res.append([x, cur_h])
            last_h = cur_h
    return res

