def trap_rain_2d(height: list[list[int]]) -> int:
    if not height or not height[0]:
        return 0
    m, n = len(height), len(height[0])
    if m < 3 or n < 3:
        return 0

    visited = [[False] * n for _ in range(m)]
    heap = []

    # Initialize min-heap with all border cells
    for i in range(m):
        for j in (0, n - 1):
            heapq.heappush(heap, (height[i][j], i, j))
            visited[i][j] = True
    for j in range(1, n - 1):
        for i in (0, m - 1):
            heapq.heappush(heap, (height[i][j], i, j))
            visited[i][j] = True

    total_water = 0
    directions = ((0, 1), (0, -1), (1, 0), (-1, 0))

    while heap:
        h, x, y = heapq.heappop(heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                if height[nx][ny] < h:
                    total_water += h - height[nx][ny]
                    heapq.heappush(heap, (h, nx, ny))
                else:
                    heapq.heappush(heap, (height[nx][ny], nx, ny))

    return total_water

