def alien_order(words: list[str]) -> str:
    # Collect all unique characters present in the words
    chars = set()
    for w in words:
        chars.update(w)

    # If no characters, return empty string
    if not chars:
        return ""

    # Initialize adjacency list and in-degree map for topological sort
    adj = {c: set() for c in chars}
    in_degree = {c: 0 for c in chars}

    # Build the graph based on adjacent word pairs
    for i in range(len(words) - 1):
        w1 = words[i]
        w2 = words[i+1]

        # Find the first differing character
        min_len = min(len(w1), len(w2))
        found_diff = False
        for j in range(min_len):
            if w1[j] != w2[j]:
                u, v = w1[j], w2[j]
                # Add edge u -> v if not already present
                if v not in adj[u]:
                    adj[u].add(v)
                    in_degree[v] += 1
                found_diff = True
                break

        # If no difference found, check for prefix violation
        # w1 cannot be longer than w2 if w2 is a prefix of w1
        if not found_diff:
            if len(w1) > len(w2):
                return ""

    # Perform topological sort using a min-heap to ensure lexicographically smallest order
    heap = []
    for c in chars:
        if in_degree[c] == 0:
            heapq.heappush(heap, c)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If the result doesn't contain all characters, there is a cycle
    if len(result) != len(chars):
        return ""

    return "".join(result)

