def word_ladders(begin: str, end: str, words: list[str]) -> list[list[str]]:
    if end not in words:
        return []

    words_set = set(words)
    L = len(begin)
    # Precompute relevant characters to limit neighbor generation
    chars = sorted(set(''.join(words) + begin + end))

    parents = defaultdict(list)
    visited = set()
    queue = deque([begin])
    found = False

    while queue:
        level_size = len(queue)
        level_visited = set()
        for _ in range(level_size):
            curr = queue.popleft()
            for i in range(L):
                for c in chars:
                    if c == curr[i]:
                        continue
                    new_word = curr[:i] + c + curr[i+1:]
                    if new_word in words_set and new_word not in visited:
                        if new_word not in level_visited:
                            queue.append(new_word)
                            level_visited.add(new_word)
                        parents[new_word].append(curr)
                        if new_word == end:
                            found = True
        visited.update(level_visited)
        if found:
            break

    if end not in parents:
        return []

    memo = {}
    def get_paths(node: str) -> list[list[str]]:
        if node == begin:
            return [[begin]]
        if node in memo:
            return memo[node]
        res = []
        for p in parents[node]:
            for path in get_paths(p):
                res.append(path + [node])
        memo[node] = res
        return res

    return sorted(get_paths(end))

from collections import deque, defaultdict

def word_ladders(begin: str, end: str, words: list[str]) -> list[list[str]]:
    word_set = set(words)
    if end not in word_set:
        return []

    word_set.discard(begin)

    parents = defaultdict(list)
    distance = {begin: 0}
    queue = deque([begin])
    found = False

    # Collect all characters that appear in the dictionary or begin
    alphabet = set("".join(words) + begin)

    while queue and not found:
        level_size = len(queue)
        visited_this_level = set()

        for _ in range(level_size):
            curr = queue.popleft()
            if curr == end:
                found = True
                continue

            curr_dist = distance[curr]
            curr_list = list(curr)
            for i in range(len(curr_list)):
                original_char = curr_list[i]
                for char in alphabet:
                    if char == original_char:
                        continue
                    curr_list[i] = char
                    neighbor = "".join(curr_list)
                    if neighbor in word_set:
                        if neighbor not in distance:
                            distance[neighbor] = curr_dist + 1
                            parents[neighbor].append(curr)
                            visited_this_level.add(neighbor)
                            queue.append(neighbor)
                        elif distance[neighbor] == curr_dist + 1:
                            parents[neighbor].append(curr)
                curr_list[i] = original_char

        word_set -= visited_this_level

    if not found:
        return []

    paths = []
    def backtrack(word, path):
        if word == begin:
            paths.append(path[::-1])
            return
        for parent in parents[word]:
            backtrack(parent, path + [parent])

    backtrack(end, [end])
    paths.sort()
    return paths

