from collections import deque

def word_ladders(begin: str, end: str, words: list[str]) -> list[list[str]]:
    word_set = set(words)
    if end not in word_set:
        return []

    dist = {begin: 0}
    parents = {begin: []}
    queue = deque([begin])
    found = False
    current_dist = 0

    while queue and not found:
        current_dist += 1
        for _ in range(len(queue)):
            curr = queue.popleft()
            for i in range(len(curr)):
                orig = curr[i]
                for c in string.ascii_lowercase:
                    if c == orig:
                        continue
                    nxt = curr[:i] + c + curr[i+1:]
                    if nxt in word_set:
                        if nxt not in dist:
                            dist[nxt] = current_dist
                            parents[nxt] = [curr]
                            queue.append(nxt)
                        elif dist[nxt] == current_dist:
                            parents[nxt].append(curr)
        if end in dist:
            found = True

    if not found:
        return []

    paths = []
    path = [end]
    def backtrack(word):
        if word == begin:
            paths.append(list(reversed(path)))
            return
        for p in parents[word]:
            path.append(p)
            backtrack(p)
            path.pop()

    backtrack(end)
    paths.sort()
    return paths

from typing import List
from collections import deque

def word_ladders(begin: str, end: str, words: List[str]) -> List[List[str]]:
    if end not in words:
        return []

    word_set = set(words)
    word_set.discard(begin)

    dist = {begin: 0}
    parents = {begin: []}
    queue = deque([begin])
    found = False

    while queue and not found:
        level_size = len(queue)
        level_visited = set()
        for _ in range(level_size):
            curr = queue.popleft()
            for word in word_set:
                diff = 0
                for c1, c2 in zip(curr, word):
                    if c1 != c2:
                        diff += 1
                        if diff > 1:
                            break
                if diff == 1:
                    if word not in dist:
                        dist[word] = dist[curr] + 1
                        parents[word] = [curr]
                        level_visited.add(word)
                    elif dist[word] == dist[curr] + 1:
                        parents[word].append(curr)
                        level_visited.add(word)
        if end in level_visited:
            found = True
        else:
            queue.extend(level_visited)

    if end not in dist:
        return []

    paths = []
    stack = [(end, [end])]
    while stack:
        curr, path = stack.pop()
        if curr == begin:
            paths.append(path[::-1])
            continue
        for p in parents[curr]:
            stack.append((p, path + [p]))

    paths.sort()
    return paths

import bisect
from typing import List

def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""
    n, m = len(s), len(t)
    if n < m:
        return ""

    # Group indices by character for O(log n) lookups
    pos: dict[str, List[int]] = {}
    for idx, ch in enumerate(s):
        pos.setdefault(ch, []).append(idx)

    best_len = n + 1
    best_start = -1

    # Only consider starting positions where s[i] == t[0]
    starts = pos.get(t[0], [])
    for i in starts:
        if i + m > n:
            break

        curr = i
        k = 0
        while k < m:
            chars = pos.get(t[k], [])
            idx = bisect.bisect_left(chars, curr)
            if idx == len(chars):
                break
            curr = chars[idx]
            k += 1
        else:
            length = curr - i + 1
            if length < best_len:
                best_len = length
                best_start = i
                # Early exit: cannot get shorter than t itself
                if best_len == m:
                    return s[best_start:best_start + best_len]

    return s[best_start:best_start + best_len] if best_start != -1 else ""

def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""
    n = len(s)
    if n == 0:
        return ""

    # Map each unique character in t to a 0-based index
    unique_chars = set(t)
    char_to_idx = {c: i for i, c in enumerate(unique_chars)}
    K = len(unique_chars)

    # Precompute next occurrence for each character in t
    # next_occ[k][i] stores the smallest index >= i where character k appears in s
    next_occ = [[-1] * (n + 1) for _ in range(K)]
    for c, idx in char_to_idx.items():
        arr = next_occ[idx]
        last = -1
        for i in range(n - 1, -1, -1):
            if s[i] == c:
                last = i
            arr[i] = last

    # Convert t to a list of precomputed indices for fast lookup
    t_indices = [char_to_idx[c] for c in t]

    best_len = float('inf')
    best_start = -1

    # Try to match t starting at each position i in s
    for i in range(n):
        curr = i
        for idx in t_indices:
            nxt = next_occ[idx][curr]
            if nxt == -1:
                break
            curr = nxt + 1
        else:
            length = curr - i
            if length < best_len:
                best_len = length
                best_start = i

    if best_start == -1:
        return ""
    return s[best_start : best_start + best_len]

def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""
    n, m = len(s), len(t)
    if n < m:
        return ""

    # Map each unique character in t to a compact index 0..u-1
    t_map = {}
    u = 0
    for c in t:
        if c not in t_map:
            t_map[c] = u
            u += 1

    # next_occ[i][k] stores the smallest index >= i where s[index] == unique_char_k, or -1
    # Initialize with -1
    next_occ = [[-1] * u for _ in range(n + 1)]

    # Fill backwards: copy next row and update current character
    for i in range(n - 1, -1, -1):
        next_occ[i] = next_occ[i+1][:]
        c = s[i]
        if c in t_map:
            next_occ[i][t_map[c]] = i

    # Precompute t's character indices to avoid dict lookups in the tight loop
    t_indices = [t_map[c] for c in t]

    best_len = n + 1
    best_start = 0

    for i in range(n):
        # Optimization: if remaining length cannot beat best_len, stop
        if n - i <= best_len:
            break

        curr = i
        possible = True
        for idx in t_indices:
            if next_occ[curr][idx] == -1:
                possible = False
                break
            curr = next_occ[curr][idx] + 1

        if possible:
            length = curr - i
            if length < best_len:
                best_len = length
                best_start = i

    if best_len > n:
        return ""
    return s[best_start:best_start + best_len]

