def bool_equiv(a: str, b: str) -> bool:
    """
    Returns True if two propositional formulas are logically equivalent.
    Raises ValueError if formulas are malformed.
    """
    # 1. Tokenize
    try:
        tokens_a = tokenize(a)
        tokens_b = tokenize(b)
    except ValueError as e:
        raise ValueError(f"Malformed formula: {e}")

    # 2. Parse into AST
    try:
        ast_a = parse_expr(tokens_a)
        if tokens_a.pos != len(tokens_a.tokens):
            raise ValueError("Unexpected tokens at end of formula")

        ast_b = parse_expr(tokens_b)
        if tokens_b.pos != len(tokens_b.tokens):
            raise ValueError("Unexpected tokens at end of formula")
    except ValueError as e:
        raise ValueError(f"Malformed formula: {e}")

    # 3. Collect variables
    vars_a = collect_vars(ast_a)
    vars_b = collect_vars(ast_b)
    all_vars = sorted(list(vars_a | vars_b))

    # Check constraint: at most 12 distinct variables
    if len(all_vars) > 12:
        # The problem statement says "At most 12 distinct variables in total".
        # It doesn't explicitly say to raise error if > 12, but implies it's a constraint.
        # Usually this implies we can brute force. If > 12, 2^12 is small, 2^13 is 8192.
        # It's still computable, but maybe we should just proceed or raise?
        # "At most 12 distinct variables in total" sounds like a guarantee/precondition.
        # If violated, behavior is undefined or we can just handle it (it's fast enough up to ~20).
        # But strictly, if it's a constraint, maybe ignore or just proceed.
        # Given "Raise ValueError if either formula is malformed", this might not be malformed.
        # We will proceed.
        pass

    # 4. Evaluate
    num_vars = len(all_vars)
    num_assignments = 1 << num_vars

    for i in range(num_assignments):
        assignment = {}
        for j in range(num_vars):
            assignment[all_vars[j]] = bool((i >> j) & 1)

        val_a = evaluate(ast_a, assignment)
        val_b = evaluate(ast_b, assignment)

        if val_a != val_b:
            return False

    return True

def tokenize(s: str):
    """
    Tokenizes the input string into a list of tokens.
    Tokens are tuples like ('VAR', 'name'), ('!',), ('&',), etc.
    """
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue

        if c.isalpha() and c.islower():
            j = i
            while j < n and s[j].isalpha() and s[j].islower():
                j += 1
            tokens.append(('VAR', s[i:j]))
            i = j
        elif c == '!':
            tokens.append(('!',))
            i += 1
        elif c == '&':
            tokens.append(('&',))
            i += 1
        elif c == '|':
            tokens.append(('|',))
            i += 1
        elif c == '(':
            tokens.append(('(',))
            i += 1
        elif c == ')':
            tokens.append((')',))
            i += 1
        elif c == '-':
            if i + 1 < n and s[i+1] == '>':
                tokens.append(('->',))
                i += 2
            else:
                raise ValueError(f"Unexpected character '-' at index {i}")
        elif c == '<':
            if i + 2 < n and s[i+1] == '-' and s[i+2] == '>':
                tokens.append(('<->',))
                i += 3
            else:
                raise ValueError(f"Unexpected character '<' at index {i}")
        else:
            raise ValueError(f"Unexpected character '{c}' at index {i}")

    return type('TokenList', (), {'tokens': tokens, 'pos': 0})

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens.tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        if self.pos >= len(self.tokens):
            raise ValueError("Unexpected end of input")
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def expect(self, val):
        t = self.peek()
        if t != val:
            raise ValueError(f"Expected {val}, got {t}")
        return self.consume()

def parse_expr(tokens):
    parser = Parser(tokens)
    ast = parser.parse_expr()
    if parser.peek() is not None:
        raise ValueError("Unexpected tokens after expression")
    return ast

class ParserRecursive:
    def __init__(self, tokens):
        self.tokens = tokens.tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        if self.pos >= len(self.tokens):
            raise ValueError("Unexpected end of input")
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def parse_expr(self):
        # < is left-associative
        left = self.parse_implies()
        while self.peek() == ('<->',):
            self.consume()
            right = self.parse_implies()
            left = ('<->', left, right)
        return left

    def parse_implies(self):
        # -> is right-associative
        left = self.parse_or()
        if self.peek() == ('->',):
            self.consume()
            right = self.parse_implies() # Right recursion
            return ('->', left, right)
        return left

    def parse_or(self):
        # | is left-associative (assumed standard)
        left = self.parse_and()
        while self.peek() == ('|',):
            self.consume()
            right = self.parse_and()
            left = ('|', left, right)
        return left

    def parse_and(self):
        # & is left-associative (assumed standard)
        left = self.parse_not()
        while self.peek() == ('&',):
            self.consume()
            right = self.parse_not()
            left = ('&', left, right)
        return left

    def parse_not(self):
        # ! is prefix, right-associative (unary)
        if self.peek() == ('!',):
            self.consume()
            operand = self.parse_not()
            return ('!', operand)
        return self.parse_atom()

    def parse_atom(self):
        t = self.peek()
        if t is None:
            raise ValueError("Unexpected end of input")

        if t == ('(',):
            self.consume()
            expr = self.parse_expr()
            if self.peek() != (')',):
                raise ValueError("Expected ')'")
            self.consume()
            return expr
        elif t[0] == 'VAR':
            self.consume()
            return ('VAR', t[1])
        else:
            # Unexpected token like operator or closing paren
            raise ValueError(f"Unexpected token {t}")

def collect_vars(node):
    if node is None:
        return set()
    if node[0] == 'VAR':
        return {node[1]}
    if node[0] == '!':
        return collect_vars(node[1])
    # Binary operators
    return collect_vars(node[1]) | collect_vars(node[2])

def evaluate(node, assignment):
    if node is None:
        return False # Should not happen for valid formulas
    op = node[0]
    if op == 'VAR':
        return assignment[node[1]]
    elif op == '!':
        return not evaluate(node[1], assignment)
    elif op == '&':
        return evaluate(node[1], assignment) and evaluate(node[2], assignment)
    elif op == '|':
        return evaluate(node[1], assignment) or evaluate(node[2], assignment)
    elif op == '->':
        # Implication: A -> B is equivalent to (not A) or B
        return (not evaluate(node[1], assignment)) or evaluate(node[2], assignment)
    elif op == '<->':
        # Equivalence: A <-> B is equivalent to (A == B)
        return evaluate(node[1], assignment) == evaluate(node[2], assignment)
    else:
        raise ValueError(f"Unknown operator {op}")

def parse_expr(tokens):
    parser = ParserRecursive(tokens)
    ast = parser.parse_expr()
    if parser.peek() is not None:
        raise ValueError("Unexpected tokens after expression")
    return ast

def bool_equiv(a: str, b: str) -> bool:
    ast1 = parse(a)
    ast2 = parse(b)

    vars1 = collect_vars(ast1)
    vars2 = collect_vars(ast2)
    all_vars = sorted(vars1 | vars2)

    n = len(all_vars)
    for i in range(1 << n):
        assignment = {all_vars[j]: bool((i >> j) & 1) for j in range(n)}
        if evaluate(ast1, assignment) != evaluate(ast2, assignment):
            return False
    return True


def tokenize(s: str):
    tokens = []
