class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def consume(self, expected_type=None):
        tok = self.tokens[self.pos]
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {tok[0]}")
        self.pos += 1
        return tok

    def parse(self):
        node = self.parse_equiv()
        if self.peek()[0] != 'EOF':
            raise ValueError(f"Unexpected token after formula: {self.peek()}")
        return node

    def parse_equiv(self):
        # Left-associative
        left = self.parse_imp()
        while self.peek()[0] == 'EQUIV':
            self.consume('EQUIV')
            right = self.parse_imp()
            left = ('<->', left, right)
        return left

    def parse_imp(self):
        # Right-associative
        left = self.parse_or()
        if self.peek()[0] == 'IMP':
            self.consume('IMP')
            right = self.parse_imp()
            return ('->', left, right)
        return left

    def parse_or(self):
        left = self.parse_and()
        while self.peek()[0] == 'OR':
            self.consume('OR')
            right = self.parse_and()
            left = ('|', left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.peek()[0] == 'AND':
            self.consume('AND')
            right = self.parse_not()
            left = ('&', left, right)
        return left

    def parse_not(self):
        if self.peek()[0] == 'NOT':
            self.consume('NOT')
            return ('!', self.parse_not())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.peek()
        if tok[0] == 'LPAREN':
            self.consume('LPAREN')
            node = self.parse_equiv()
            if self.peek()[0] != 'RPAREN':
                raise ValueError("Missing closing parenthesis")
            self.consume('RPAREN')
            return node
        elif tok[0] == 'VAR':
            self.consume('VAR')
            return ('VAR', tok[1])
        else:
            raise ValueError(f"Unexpected token in primary: {tok}")


def parse(s: str):
    tokens = tokenize(s)
    parser = Parser(tokens)
    return parser.parse()


def collect_vars(node):
    if node[0] == 'VAR':
        return {node[1]}
    elif node[0] == '!':
        return collect_vars(node[1])
    else:
        return collect_vars(node[1]) | collect_vars(node[2])


def evaluate(node, assignment):
    if node[0] == 'VAR':
        return assignment[node[1]]
    elif node[0] == '!':
        return not evaluate(node[1], assignment)
    elif node[0] == '&':
        return evaluate(node[1], assignment) and evaluate(node[2], assignment)
    elif node[0] == '|':
        return evaluate(node[1], assignment) or evaluate(node[2], assignment)
    elif node[0] == '->':
        return not evaluate(node[1], assignment) or evaluate(node[2], assignment)
    elif node[0] == '<->':
        return evaluate(node[1], assignment) == evaluate(node[2], assignment)

import sys
from typing import List, Tuple, Optional, Dict, Any, Set

# Token types
EOF = 'EOF'

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value
    def __repr__(self):
        return f"Token({self.type}, {self.value!r})"

class Node:
    def __init__(self, type: str, left=None, right=None, name=None, child=None):
        self.type = type
        self.left = left
        self.right = right
        self.name = name
        self.child = child

class Parser:
    def __init__(self, text: str):
        self.tokens = self._tokenize(text)
        self.pos = 0

    def _tokenize(self, text: str) -> List[Token]:
        tokens = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isspace():
                i += 1
                continue

            if text[i] == '<':
                if i + 2 < n and text[i+1] == '-' and text[i+2] == '>':
                    tokens.append(Token('<->', '<->'))
                    i += 3
                else:
                    raise ValueError(f"Malformed input: unexpected '<' at position {i}")
            elif text[i] == '-':
                if i + 1 < n and text[i+1] == '>':
                    tokens.append(Token('->', '->'))
                    i += 2
                else:
                    raise ValueError(f"Malformed input: unexpected '-' at position {i}")
            elif text[i] == '!':
                tokens.append(Token('!', '!'))
                i += 1
            elif text[i] == '&':
                tokens.append(Token('&', '&'))
                i += 1
            elif text[i] == '|':
                tokens.append(Token('|', '|'))
                i += 1
            elif text[i] == '(':
                tokens.append(Token('(', '('))
                i += 1
            elif text[i] == ')':
                tokens.append(Token(')', ')'))
                i += 1
            elif text[i].islower():
                j = i
                while j < n and text[j].islower():
                    j += 1
                tokens.append(Token('VAR', text[i:j]))
                i = j
            else:
                raise ValueError(f"Malformed input: unexpected character '{text[i]}' at position {i}")
        return tokens

    def current(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return Token(EOF, None)

    def consume(self, expected_type: Optional[str] = None) -> Token:
        tok = self.current()
        if tok.type == EOF:
            raise ValueError("Malformed input: unexpected end of input")
        if expected_type is not None and tok.type != expected_type:
            raise ValueError(f"Malformed input: expected {expected_type}, got {tok.type}")
        self.pos += 1
        return tok

    def match(self, type: str) -> bool:
        return self.current().type == type

    def parse(self) -> Node:
        node = self.parse_expr()
        if self.current().type != EOF:
            raise ValueError("Malformed input: unexpected token at end")
        return node

    # Grammar:
    # Expr -> Imp ("<->" Imp)*
    # Imp  -> Or ("->" Imp)?  (Right associative)
    # Or   -> And ("|" And)*
    # And  -> Not ("&" Not)*
    # Not  -> "!" Not | Atom
    # Atom -> VAR | "(" Expr ")"

    def parse_expr(self) -> Node:
        left = self.parse_imp()
        while self.match('<->'):
            self.consume('<->')
            right = self.parse_imp()
            left = Node('<->', left, right)
        return left

    def parse_imp(self) -> Node:
        left = self.parse_or()
        if self.match('->'):
            self.consume('->')
            right = self.parse_imp() # Right recursive for right-associativity
            return Node('->', left, right)
        return left

    def parse_or(self) -> Node:
        left = self.parse_and()
        while self.match('|'):
            self.consume('|')
            right = self.parse_and()
            left = Node('|', left, right)
        return left

    def parse_and(self) -> Node:
        left = self.parse_not()
        while self.match('&'):
            self.consume('&')
            right = self.parse_not()
            left = Node('&', left, right)
        return left

    def parse_not(self) -> Node:
        if self.match('!'):
            self.consume('!')
            child = self.parse_not() # Right recursive (unary binds tightest)
            return Node('!', child=child)
        return self.parse_atom()

    def parse_atom(self) -> Node:
        if self.match('VAR'):
            return Node('VAR', name=self.consume('VAR').value)
        elif self.match('('):
            self.consume('(')
            node = self.parse_expr()
            self.consume(')')
            return node
        else:
            raise ValueError("Malformed input: expected variable or '('")

def get_variables(node: Node) -> Set[str]:
    if node is None:
        return set()
    if node.type == 'VAR':
        return {node.name}
    vars_left = get_variables(node.left)
    vars_right = get_variables(node.right)
    return vars_left.union(vars_right)

def evaluate(node: Node, assignment: Dict[str, bool]) -> bool:
    if node.type == 'VAR':
        return assignment[node.name]
    elif node.type == '!':
        return not evaluate(node.child, assignment)
    elif node.type == '&':
        return evaluate(node.left, assignment) and evaluate(node.right, assignment)
    elif node.type == '|':
        return evaluate(node.left, assignment) or evaluate(node.right, assignment)
    elif node.type == '->':
        # Implication: (not left) or right
        return (not evaluate(node.left, assignment)) or evaluate(node.right, assignment)
    elif node.type == '<->':
        return evaluate(node.left, assignment) == evaluate(node.right, assignment)
    else:
        raise ValueError(f"Unknown node type: {node.type}")

def bool_equiv(a: str, b: str) -> bool:
    try:
        parser_a = Parser(a)
        tree_a = parser_a.parse()

        parser_b = Parser(b)
        tree_b = parser_b.parse()
    except ValueError:
        raise

    vars_a = get_variables(tree_a)
    vars_b = get_variables(tree_b)
    all_vars = sorted(list(vars_a.union(vars_b)))

    n = len(all_vars)
    if n > 12:
        # Although problem says at most 12, we can handle it, but 2^12 is limit for reasonable time.
        # If more, we might TLE, but specification guarantees <= 12.
        pass

    # Check all 2^n assignments
    for i in range(1 << n):
        assignment = {}
        for j in range(n):
            assignment[all_vars[j]] = bool((i >> j) & 1)

        val_a = evaluate(tree_a, assignment)
        val_b = evaluate(tree_b, assignment)

        if val_a != val_b:
            return False

    return True

def bool_equiv(a: str, b: str) -> bool:
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isspace():
                i += 1
                continue
            if s[i].islower():
                j = i
                while j < n and s[j].islower():
                    j += 1
                tokens.append(('VAR', s[i:j]))
                i = j
            elif s[i] == '(':
                tokens.append(('LPAREN', '('))
                i += 1
            elif s[i] == ')':
                tokens.append(('RPAREN', ')'))
                i += 1
            elif s[i] == '!':
                tokens.append(('OP', '!'))
                i += 1
            elif s[i] == '&':
                tokens.append(('OP', '&'))
                i += 1
            elif s[i] == '|':
                tokens.append(('OP', '|'))
                i += 1
            elif s[i] == '<':
                if i + 1 < n and s[i+1] == '-':
                    tokens.append(('OP', '<->'))
                    i += 2
                else:
                    raise ValueError("Malformed formula")
            elif s[i] == '-':
                if i + 1 < n and s[i+1] == '>':
                    tokens.append(('OP', '->'))
                    i += 2
                else:
                    raise ValueError("Malformed formula")
            else:
                raise ValueError("Malformed formula")
        tokens.append(('EOF', ''))
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos]

        def consume(self, expected_type=None, expected_val=None):
            tok = self.tokens[self.pos]
            if expected_type and tok[0] != expected_type:
                raise ValueError("Malformed formula")
            if expected_val and tok[1] != expected_val:
                raise ValueError("Malformed formula")
            self.pos += 1
            return tok

        def parse_expr(self):
            left = self.parse_imp()
            while self.peek()[0] == 'OP' and self.peek()[1] == '<->':
                self.consume()
                right = self.parse_imp()
                left = ('<->', left, right)
            return left

        def parse_imp(self):
            left = self.parse_or()
            if self.peek()[0] == 'OP' and self.peek()[1] == '->':
                self.consume()
                right = self.parse_imp()
                return ('->', left, right)
            return left

        def parse_or(self):
            left = self.parse_and()
            while self.peek()[0] == 'OP' and self.peek()[1] == '|':
                self.consume()
                right = self.parse_and()
                left = ('|', left, right)
            return left

        def parse_and(self):
            left = self.parse_not()
            while self.peek()[0] == 'OP' and self.peek()[1] == '&':
                self.consume()
                right = self.parse_not()
                left = ('&', left, right)
            return left

        def parse_not(self):
            if self.peek()[0] == 'OP' and self.peek()[1] == '!':
                self.consume()
                operand = self.parse_not()
                return ('!', operand)
            return self.parse_primary()

        def parse_primary(self):
            tok = self.peek()
            if tok[0] == 'VAR':
                self.consume()
                return ('VAR', tok[1])
            elif tok[0] == 'LPAREN':
                self.consume()
                node = self.parse_expr()
                if self.peek()[0] != 'RPAREN':
                    raise ValueError("Malformed formula")
                self.consume()
                return node
            else:
                raise ValueError("Malformed formula")

    def collect_vars(node):
        if node[0] == 'VAR':
            return {node[1]}
        elif node[0] == '!':
            return collect_vars(node[1])
        else:
            return collect_vars(node[1]) | collect_vars(node[2])

    def evaluate(node, env):
        if node[0] == 'VAR':
            return env[node[1]]
        elif node[0] == '!':
            return not evaluate(node[1], env)
        elif node[0] == '&':
            return evaluate(node[1], env) and evaluate(node[2], env)
        elif node[0] == '|':
            return evaluate(node[1], env) or evaluate(node[2], env)
        elif node[0] == '->':
            return not evaluate(node[1], env) or evaluate(node[2], env)
        elif node[0] == '<->':
            return evaluate(node[1], env) == evaluate(node[2], env)
        else:
            raise ValueError("Malformed AST")

    tokens_a = tokenize(a)
    tokens_b = tokenize(b)

    parser_a = Parser(tokens_a)
    ast_a = parser_a.parse_expr()
    if parser_a.peek()[0] != 'EOF':
        raise ValueError("Malformed formula")

    parser_b = Parser(tokens_b)
    ast_b = parser_b.parse_expr()
    if parser_b.peek()[0] != 'EOF':
        raise ValueError("Malformed formula")

    vars_set = collect_vars(ast_a) | collect_vars(ast_b)
    var_list = sorted(vars_set)
    n = len(var_list)

    for i in range(1 << n):
        env = {var_list[j]: bool(i & (1 << j)) for j in range(n)}
        val_a = evaluate(ast_a, env)
        val_b = evaluate(ast_b, env)
        if val_a != val_b:
            return False
    return True

def determinant(m: list[list[int]]) -> int:
    n = len(m)
    if n == 0:
        return 1
    mat = [row[:] for row in m]
    det_sign = 1
    prev_pivot = 1
    for i in range(n - 1):
        pivot_row = i
        while pivot_row < n and mat[pivot_row][i] == 0:
            pivot_row += 1
        if pivot_row == n:
            return 0
        if pivot_row != i:
            mat[i], mat[pivot_row] = mat[pivot_row], mat[i]
            det_sign = -det_sign
        pivot = mat[i][i]
        for j in range(i + 1, n):
            for k in range(i + 1, n):
                mat[j][k] = (mat[j][k] * pivot - mat[j][i] * mat[i][k]) // prev_pivot
        prev_pivot = pivot
    return det_sign * mat[n-1][n-1]

def next_palindrome(s: str) -> str:
    n = len(s)
    if all(c == '9' for c in s):
        return '1' + '0' * (n - 1) + '1'

    digits = [int(c) for c in s]
    orig = digits[:]

    # Mirror the left half to the right half
    for i in range(n // 2):
        digits[n - 1 - i] = digits[i]

    # If the mirrored number is not strictly greater, increment the middle
    if digits <= orig:
        i = (n - 1) // 2
        while i >= 0:
            digits[i] += 1
            if digits[i] < 10:
                break
            digits[i] = 0
            i -= 1
        # Mirror again after incrementing the middle
        for j in range(n // 2):
            digits[n - 1 - j] = digits[j]

    return ''.join(map(str, digits))

def next_palindrome(s: str) -> str:
    n = len(s)
    if n == 0:
        return "1"

    # Helper to construct palindrome from left half
    def make_palindrome(left: str, n: int) -> str:
        if n % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[:-1][::-1]

    # 1. Construct the mirror palindrome
    mid = (n + 1) // 2
    left_half = s[:mid]
    candidate = make_palindrome(left_half, n)

    # 2. Check if candidate is strictly greater
    if candidate > s:
        return candidate

    # 3. If not, we need to increment the left half and mirror again
    # Convert left half to integer, add 1, convert back to string
    # Since s can be large, we use Python's arbitrary precision integers
    try:
        new_left_int = int(left_half) + 1
        new_left = str(new_left_int)
    except ValueError:
        # Should not happen as s consists of digits
        return ""

    # Check for overflow (length increase)
    if len(new_left) > len(left_half):
        # Overflow means the number was all 9s (e.g., 99 -> 100)
        # The next palindrome is 10...01
        return "1" + "0" * (n - 1) + "1"

    # Construct the new palindrome
    return make_palindrome(new_left, n)

def count_digit(n: int, d: int) -> int:
    count = 0
    factor = 1
    while factor <= n:
        higher = n // (factor * 10)
        current = (n // factor) % 10
        lower = n % factor

        if d == 0:
            count += higher * factor
            if current == 0:
                count += lower + 1 - factor
        else:
            count += higher * factor
            if current > d:
                count += factor
            elif current == d:
                count += lower + 1

        factor *= 10

    if d == 0:
        count += 1

    return count

import bisect

def weighted_interval(jobs: list[tuple[int, int, int]]) -> list[int]:
    if not jobs:
        return []

    n = len(jobs)
    indexed_jobs = [(s, e, w, i) for i, (s, e, w) in enumerate(jobs)]
    indexed_jobs.sort(key=lambda x: x[1])

    ends = [j[1] for j in indexed_jobs]
    p = [-1] * n
    for i in range(n):
        p[i] = bisect.bisect_right(ends, indexed_jobs[i][0]) - 1

    dp = [None] * n
    for i in range(n):
        w_take = indexed_jobs[i][2]
        idx_take = [indexed_jobs[i][3]]
        prev = p[i]
        if prev == -1:
            w_prev, idx_prev = 0, []
        else:
            w_prev, idx_prev = dp[prev]
        take_w = w_prev + w_take
        take_idx = sorted(idx_prev + idx_take)

        if i == 0:
            skip_w, skip_idx = 0, []
        else:
            skip_w, skip_idx = dp[i-1]

        if take_w > skip_w:
            dp[i] = (take_w, take_idx)
        elif take_w < skip_w:
            dp[i] = (skip_w, skip_idx)
        else:
            dp[i] = (take_w, take_idx if take_idx < skip_idx else skip_idx)

    return dp[n-1][1]

def maximal_rectangle(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return 0

    n = len(grid[0])
    heights = [0] * n
    max_area = 0

    for row in grid:
        for j, c in enumerate(row):
            heights[j] = heights[j] + 1 if c == '1' else 0

        stack = []
        for i in range(n + 1):
            h = heights[i] if i < n else 0
            while stack and heights[stack[-1]] >= h:
                height = heights[stack.pop()]
                width = i if not stack else i - stack[-1] - 1
                area = height * width
                if area > max_area:
                    max_area = area
            stack.append(i)

    return max_area

