def merge_stones(stones: list[int], k: int) -> int:
    n = len(stones)
    if n == 1:
        return 0
    if (n - 1) % (k - 1) != 0:
        return -1

    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + stones[i]

    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            # Try all valid split points. The step k-1 ensures we split into 
            # sub-ranges that can each be reduced to 1 pile, accumulating to k piles total.
            for m in range(i, j, k - 1):
                dp[i][j] = min(dp[i][j], dp[i][m] + dp[m + 1][j])
            # If the current range can be fully merged into 1 pile, add the cost of the final merge
            if (j - i) % (k - 1) == 0:
                dp[i][j] += prefix[j + 1] - prefix[i]

    return dp[0][n - 1]

from fractions import Fraction

def reach_target(nums: list[int], target: int) -> str | None:
    target_frac = Fraction(target)

    def solve(current_nums):
        if len(current_nums) == 1:
            val, expr = current_nums[0]
            if val == target_frac:
                return expr[1:-1] if expr.startswith('(') and expr.endswith(')') else expr
            return None

        n = len(current_nums)
        for i in range(n):
            for j in range(i + 1, n):
                val1, expr1 = current_nums[i]
                val2, expr2 = current_nums[j]

                # Efficiently build the list of remaining numbers
                remaining = current_nums[:i] + current_nums[i+1:j] + current_nums[j+1:]

                # Generate all valid binary operations
                ops = [
                    ('+', val1 + val2, f"({expr1} + {expr2})"),
                    ('-', val1 - val2, f"({expr1} - {expr2})"),
                    ('-', val2 - val1, f"({expr2} - {expr1})"),
                    ('*', val1 * val2, f"({expr1} * {expr2})"),
                ]
                if val2 != 0:
                    ops.append(('/', val1 / val2, f"({expr1} / {expr2})"))
                if val1 != 0:
                    ops.append(('/', val2 / val1, f"({expr2} / {expr1})"))

                for _, res_val, res_expr in ops:
                    new_nums = remaining + [(res_val, res_expr)]
                    res = solve(new_nums)
                    if res is not None:
                        return res
        return None

    initial_nums = [(Fraction(n), str(n)) for n in nums]
    return solve(initial_nums)

def fraction_to_base(p: int, q: int, b: int) -> str:
    if q == 0:
        raise ValueError("Denominator q cannot be zero")

    # Handle zero case explicitly to avoid "-0"
    if p == 0:
        return "0"

    # Determine sign
    neg = (p < 0) ^ (q < 0)
    p = abs(p)
    q = abs(q)

    # Integer part
    int_part = p // q
    rem = p % q

    # Convert integer part to base b string
    if int_part == 0:
        int_str = "0"
    else:
        digits = []
        temp = int_part
        while temp > 0:
            d = temp % b
            digits.append(d)
            temp //= b
        # Digits are in reverse order
        int_str = "".join(_digit_to_char(d) for d in reversed(digits))

    if neg:
        result = "-" + int_str
    else:
        result = int_str

    if rem == 0:
        return result

    # Fractional part
    frac_digits = []
    seen_remainders = {}  # Maps remainder -> index in frac_digits where digit was generated

    # We are currently at remainder 'rem'.
    # We will generate digits until remainder repeats or becomes 0.

    while rem != 0:
        if rem in seen_remainders:
            # Repeating part detected
            start_index = seen_remainders[rem]
            non_repeating = frac_digits[:start_index]
            repeating = frac_digits[start_index:]

            frac_str = _digits_to_str(non_repeating)
            if repeating:
                frac_str += "(" + _digits_to_str(repeating) + ")"
            return result + "." + frac_str

        # Record that this remainder produced the next digit
        seen_remainders[rem] = len(frac_digits)

        # Long division step
        rem *= b
        digit = rem // q
        rem = rem % q
        frac_digits.append(digit)

        # If remainder becomes 0, it's a terminating decimal
        if rem == 0:
            return result + "." + _digits_to_str(frac_digits)

def _digit_to_char(d: int) -> str:
    if 0 <= d <= 9:
        return str(d)
    elif 10 <= d <= 35:
        return chr(ord('a') + d - 10)
    else:
        raise ValueError(f"Digit {d} out of range for base <= 36")

def _digits_to_str(digits: list) -> str:
    return "".join(_digit_to_char(d) for d in digits)

def fraction_to_base(p: int, q: int, b: int) -> str:
    # Handle sign
    negative = (p < 0) ^ (q < 0)
    p = abs(p)
    q = abs(q)

    # Integer part
    int_part = p // q
    rem = p % q

    # Convert integer part to base b
    if int_part == 0:
        int_str = "0"
    else:
        digits = []
        n = int_part
        while n > 0:
            digits.append(n % b)
            n //= b
        # Map digits to characters
        char_digits = []
        for d in reversed(digits):
            if d < 10:
                char_digits.append(chr(ord('0') + d))
            else:
                char_digits.append(chr(ord('a') + d - 10))
        int_str = "".join(char_digits)

    if rem == 0:
        return ("-" + int_str) if negative else int_str

    # Fractional part
    seen = {}
    frac_digits = []
    curr_rem = rem

    while curr_rem != 0:
        if curr_rem in seen:
            # Cycle detected
            start_index = seen[curr_rem]
            non_repeating = frac_digits[:start_index]
            repeating = frac_digits[start_index:]
            break
        else:
            seen[curr_rem] = len(frac_digits)

            # Generate next digit
            curr_rem *= b
            digit = curr_rem // q
            curr_rem %= q
            frac_digits.append(digit)
    else:
        # Terminating expansion
        non_repeating = frac_digits
        repeating = []

    # Helper to map digit integer to character
    def digit_to_char(d):
        if d < 10:
            return chr(ord('0') + d)
        else:
            return chr(ord('a') + d - 10)

    # Construct fractional string
    frac_parts = []
    if non_repeating:
        frac_parts.append("".join(digit_to_char(d) for d in non_repeating))
    if repeating:
        frac_parts.append("(" + "".join(digit_to_char(d) for d in repeating) + ")")

    frac_str = "".join(frac_parts)
    result = int_str + "." + frac_str

    if negative:
        result = "-" + result

    return result

def brace_expansion(expr: str) -> list[str]:
    class Node:
        pass

    class CharNode(Node):
        def __init__(self, c):
            self.c = c
        def evaluate(self):
            return {self.c}

    class ConcatNode(Node):
        def __init__(self, children):
            self.children = children
        def evaluate(self):
            res = {""}
            for child in self.children:
                child_vals = child.evaluate()
                new_res = set()
                for s1 in res:
                    for s2 in child_vals:
                        new_res.add(s1 + s2)
                res = new_res
            return res

    class UnionNode(Node):
        def __init__(self, children):
            self.children = children
        def evaluate(self):
            res = set()
            for child in self.children:
                res.update(child.evaluate())
            return res

    class EmptyNode(Node):
        def evaluate(self):
            return {""}

    n = len(expr)
    idx = 0

    def parse_sequence(stop_chars):
        nonlocal idx
        terms = []
        while idx < n and (stop_chars is None or expr[idx] not in stop_chars):
            if expr[idx] == '{':
                node, idx = parse_group()
                terms.append(node)
            else:
                terms.append(CharNode(expr[idx]))
                idx += 1

        if not terms:
            return (EmptyNode(), idx)
        elif len(terms) == 1:
            return (terms[0], idx)
        else:
            return (ConcatNode(terms), idx)

    def parse_group():
        nonlocal idx
        # expr[idx] is '{'
        idx += 1
        expressions = []
        while idx < n and expr[idx] != '}':
            node, idx = parse_sequence({',', '}'})
            expressions.append(node)
            if idx < n and expr[idx] == ',':
                idx += 1

        if idx < n and expr[idx] == '}':
            idx += 1

        return (UnionNode(expressions), idx)

    root, _ = parse_sequence(None)
    result_set = root.evaluate()
    return sorted(list(result_set))

def brace_expansion(expr: str) -> list[str]:
    n = len(expr)
    pos = 0

    def parse_expr():
        terms = []
        while pos < n and expr[pos] not in (',', '}'):
            terms.append(parse_term())
        if not terms:
            return {''}
        result = {''}
        for term in terms:
            result = {w + t for w in result for t in term}
        return result

    def parse_term():
        nonlocal pos
        if expr[pos] == '{':
            pos += 1
            res = parse_expr_list()
            pos += 1
            return res
        ch = expr[pos]
        pos += 1
        return {ch}

    def parse_expr_list():
        nonlocal pos
        results = []
        results.append(parse_expr())
        while pos < n and expr[pos] == ',':
            pos += 1
            results.append(parse_expr())
        return set().union(*results)

    return sorted(parse_expr())

def brace_expansion(expr: str) -> list[str]:
    n = len(expr)
    pos = 0

    def parse_expr():
        nonlocal pos
        res = ['']
        while pos < n and expr[pos] not in ',}':
            if expr[pos] == '{':
                pos += 1
                alternatives = []
                alternatives.append(parse_expr())
                while pos < n and expr[pos] == ',':
                    pos += 1
                    alternatives.append(parse_expr())
                term_res = sorted(set(word for alt in alternatives for word in alt))
                pos += 1
            else:
                term_res = [expr[pos]]
                pos += 1

            new_res = []
            for r in res:
                for t in term_res:
                    new_res.append(r + t)
            res = new_res
        return res

    return sorted(set(parse_expr()))
